1	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
2	import { toast } from "sonner";
3	import supabase from "@/lib/supabase";
4	import { useAuth } from "@/contexts/AuthContext";
5	import type { Scan, PageType } from "@/types";
6	import type { ScanRow } from "@/types/database";
7	
8	// ── Query keys ──────────────────────────────────────────────────
9	
10	export const scanKeys = {
11	  all: ["scans"] as const,
12	  lists: () => [...scanKeys.all, "list"] as const,
13	  list: (userId: string) => [...scanKeys.lists(), userId] as const,
14	  teamList: (teamId: string) => [...scanKeys.all, "team", teamId] as const,
15	  details: () => [...scanKeys.all, "detail"] as const,
16	  detail: (id: string) => [...scanKeys.details(), id] as const,
17	};
18	
19	// ── Row → App type mapper ───────────────────────────────────────
20	
21	function rowToScan(row: ScanRow): Scan {
22	  return {
23	    id: row.id,
24	    user_id: row.user_id,
25	    url: row.url,
26	    favicon_url: row.favicon_url,
27	    page_title: row.page_title,
28	    page_type: row.page_type,
29	    status: row.status,
30	    overall_score: row.overall_score,
31	    issues_found: row.issues_found,
32	    critical_issues: row.critical_issues,
33	    warnings: row.warnings,
34	    quick_wins: row.quick_wins,
35	    screenshot_url: row.screenshot_url,
36	    device: row.device,
37	    team_id: row.team_id,
38	    share_token: row.share_token,
39	    is_public: row.is_public,
40	    created_at: row.created_at,
41	    completed_at: row.completed_at,
42	  };
43	}
44	
45	// ── useScans ────────────────────────────────────────────────────
46	
47	export function useScans() {
48	  const { user } = useAuth();
49	
50	  return useQuery({
51	    queryKey: scanKeys.list(user?.id ?? ""),
52	    queryFn: async (): Promise<Scan[]> => {
53	      if (!user?.id) return [];
54	
55	      const { data, error } = await supabase
56	        .from("scans")
57	        .select("*")
58	        .eq("user_id", user.id)
59	        .order("created_at", { ascending: false });
60	
61	      if (error) throw new Error(error.message);
62	      return (data as ScanRow[]).map(rowToScan);
63	    },
64	    enabled: !!user?.id,
65	    staleTime: 1000 * 30, // 30 seconds
66	  });
67	}
68	
69	// ── useScan ─────────────────────────────────────────────────────
70	
71	export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
72	  const { user } = useAuth();
73	
74	  return useQuery({
75	    queryKey: scanKeys.detail(id ?? ""),
76	    queryFn: async (): Promise<Scan | null> => {
77	      if (!id || !user?.id) return null;
78	
79	      const { data, error } = await supabase
80	        .from("scans")
81	        .select("*")
82	        .eq("id", id)
83	        .eq("user_id", user.id)
84	        .single();
85	
86	      if (error) {
87	        if (error.code === "PGRST116") return null;
88	        throw new Error(error.message);
89	      }
90	
91	      return rowToScan(data as ScanRow);
92	    },
93	    enabled: !!id && !!user?.id,
94	    refetchInterval: options?.refetchInterval,
95	    staleTime: 0,
96	  });
97	}
98	
99	// ── useCreateScan ───────────────────────────────────────────────
100	
101	interface CreateScanInput {
102	  url: string;
103	  page_type: PageType;
104	  team_id?: string | null;
105	}
106	
107	export function useCreateScan() {
108	  const { user, refreshProfile } = useAuth();
109	  const queryClient = useQueryClient();
110	
111	  return useMutation({
112	    mutationFn: async ({ url, page_type, team_id }: CreateScanInput): Promise<Scan> => {
113	      if (!user?.id) throw new Error("Not authenticated");
114	
115	      // Insert the scan row first
116	      const { data: scanData, error: insertError } = await supabase
117	        .from("scans")
118	        .insert({
119	          user_id: user.id,
120	          url,
121	          page_type,
122	          status: "pending" as const,
123	          ...(team_id ? { team_id } : {}),
124	        })
125	        .select("*")
126	        .single();
127	
128	      if (insertError) throw new Error(insertError.message);
129	
130	      const scan = rowToScan(scanData as ScanRow);
131	
132	      // Invoke edge function — fire and don't block the return
133	      // The edge function updates the scan row when done
134	      supabase.functions
135	        .invoke("analyze-url", {
136	          body: { scan_id: scan.id, url, page_type },
137	        })
138	        .catch((err: unknown) => {
139	          console.error("Edge function invocation failed:", err);
140	          toast.error("Analysis engine failed to start. Please try re-scanning in a moment.", { duration: 6000 });
141	        });
142	
143	      return scan;
144	    },
145	    onSuccess: (data) => {
146	      if (!user?.id) return;
147	      // Optimistically prepend the new scan to the list cache
148	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
149	        prev ? [data, ...prev] : [data]
150	      );
151	      // Prime the detail cache
152	      queryClient.setQueryData(scanKeys.detail(data.id), data);
153	      // Refresh profile to show updated scans_used count
154	      refreshProfile();
155	    },
156	  });
157	}
158	
159	// ── useDeleteScan ───────────────────────────────────────────────
160	
161	export function useDeleteScan() {
162	  const { user } = useAuth();
163	  const queryClient = useQueryClient();
164	
165	  return useMutation({
166	    mutationFn: async (scanId: string): Promise<void> => {
167	      if (!user?.id) throw new Error("Not authenticated");
168	
169	      const { error } = await supabase
170	        .from("scans")
171	        .delete()
172	        .eq("id", scanId)
173	        .eq("user_id", user.id);
174	
175	      if (error) throw new Error(error.message);
176	    },
177	    onSuccess: (_data, scanId) => {
178	      if (!user?.id) return;
179	      // Remove from list cache
180	      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
181	        prev ? prev.filter((s) => s.id !== scanId) : []
182	      );
183	      // Remove detail cache
184	      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
185	    },
186	  });
187	}
188	
189	// ── useRefreshScan ──────────────────────────────────────────────
190	// Creates a new scan for the same URL/page_type as an existing scan
191	
192	export function useRefreshScan() {
193	  const createScan = useCreateScan();
194	
195	  return useMutation({
196	    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
197	      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
198	    },
199	  });
200	}
201	
202	// ── useTeamScans ────────────────────────────────────────────────
203	// Returns all scans belonging to a specific team.
204	
205	export function useTeamScans(teamId: string | undefined) {
206	  return useQuery({
207	    queryKey: scanKeys.teamList(teamId ?? ""),
208	    queryFn: async (): Promise<Scan[]> => {
209	      if (!teamId) return [];
210	
211	      const { data, error } = await supabase
212	        .from("scans")
213	        .select("*")
214	        .eq("team_id", teamId)
215	        .order("created_at", { ascending: false });
216	
217	      if (error) throw new Error(error.message);
218	      return (data as ScanRow[]).map(rowToScan);
219	    },
220	    enabled: !!teamId,
221	    staleTime: 1000 * 30,
222	  });
223	}
