1	=== use-analytics-data ===
2	import { useQuery } from "@tanstack/react-query";
3	import supabase from "@/lib/supabase";
4	import type { AnalyticsMetrics } from "@/types/index";
5	import { useIntegrations } from "./use-integrations";
6	
7	// ── Query keys ─────────────────────────────────────────────────
8	
9	export const analyticsKeys = {
10	  all: ["analytics"] as const,
11	  byUrl: (url: string) => ["analytics", url] as const,
12	};
13	
14	// ── Edge function response shapes ─────────────────────────────
15	
16	interface AnalyticsNotConnected {
17	  connected: false;
18	}
19	
20	interface AnalyticsSetupRequired {
21	  connected: true;
22	  setup_required: true;
23	}
24	
25	interface AnalyticsError {
26	  connected: true;
27	  error: string;
28	}
29	
30	interface AnalyticsSuccess {
31	  connected: true;
32	  metrics: AnalyticsMetrics;
33	}
34	
35	type FetchAnalyticsResponse =
36	  | AnalyticsNotConnected
37	  | AnalyticsSetupRequired
38	  | AnalyticsError
39	  | AnalyticsSuccess;
40	
41	// ── useGa4Connection ───────────────────────────────────────────
42	// Returns whether the current user has an active GA4 integration.
43	
44	export function useGa4Connection(): {
45	  isConnected: boolean;
46	  isLoading: boolean;
47	} {
48	  const { data: integrations = [], isLoading } = useIntegrations();
49	
50	  const isConnected = integrations.some(
51	    (i) => i.provider === "google_analytics" && i.is_active,
52	  );
53	
54	  return { isConnected, isLoading };
55	}
56	
57	// ── useAnalyticsData ───────────────────────────────────────────
58	// Fetches GA4 analytics for the given URL.
59	// Returns null when GA4 is not connected or when there is no data.
60	
61	export function useAnalyticsData(url: string): {
62	  data: AnalyticsMetrics | null;
63	  isLoading: boolean;
64	  isError: boolean;
65	  setupRequired: boolean;
66	  errorMessage: string | null;
67	  notConnected: boolean;
68	} {
69	  const { isConnected } = useGa4Connection();
70	
71	  const query = useQuery({
72	    queryKey: analyticsKeys.byUrl(url),
73	    queryFn: async (): Promise<FetchAnalyticsResponse> => {
74	      const { data, error } = await supabase.functions.invoke<FetchAnalyticsResponse>(
75	        "fetch-analytics",
76	        { body: { url } },
77	      );
78	
79	      if (error) throw new Error(error.message);
80	      if (!data) throw new Error("Empty response from fetch-analytics");
81	      return data;
82	    },
83	    enabled: isConnected && url.length > 0,
84	    staleTime: 1000 * 60 * 5, // 5 minutes — GA4 data doesn't change per second
85	    retry: 1,
86	  });
87	
88	  const response = query.data;
89	
90	  if (!response) {
91	    return {
92	      data: null,
93	      isLoading: query.isLoading,
94	      isError: query.isError,
95	      setupRequired: false,
96	      errorMessage: null,
97	      notConnected: !isConnected,
98	    };
99	  }
100	
101	  if (!response.connected) {
102	    return {
103	      data: null,
104	      isLoading: false,
105	      isError: false,
106	      setupRequired: false,
107	      errorMessage: null,
108	      notConnected: true,
109	    };
110	  }
111	
112	  if ("setup_required" in response && response.setup_required) {
113	    return {
114	      data: null,
115	      isLoading: false,
116	      isError: false,
117	      setupRequired: true,
118	      errorMessage: null,
119	      notConnected: false,
120	    };
121	  }
122	
123	  if ("error" in response && response.error) {
124	    return {
125	      data: null,
126	      isLoading: false,
127	      isError: true,
128	      setupRequired: false,
129	      errorMessage: response.error,
130	      notConnected: false,
131	    };
132	  }
133	
134	  if ("metrics" in response && response.metrics) {
135	    return {
136	      data: response.metrics,
137	      isLoading: false,
138	      isError: false,
139	      setupRequired: false,
140	      errorMessage: null,
141	      notConnected: false,
142	    };
143	  }
144	
145	  return {
146	    data: null,
147	    isLoading: false,
148	    isError: false,
149	    setupRequired: false,
150	    errorMessage: null,
151	    notConnected: false,
152	  };
153	}
