155	=== use-api-keys ===
156	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
157	import { toast } from "sonner";
158	import supabase from "@/lib/supabase";
159	import { useAuth } from "@/contexts/AuthContext";
160	import type { ApiKey } from "@/types";
161	
162	// ── SHA-256 helper (same algorithm as edge function) ──────────
163	
164	async function hashApiKey(key: string): Promise<string> {
165	  const encoded = new TextEncoder().encode(key);
166	  const hashBuffer = await crypto.subtle.digest("SHA-256", encoded);
167	  const hashArray = Array.from(new Uint8Array(hashBuffer));
168	  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
169	}
170	
171	// ── useApiKeys ────────────────────────────────────────────────
172	// Fetches active (non-revoked) API keys for the current user.
173	
174	export function useApiKeys() {
175	  const { user } = useAuth();
176	
177	  return useQuery<ApiKey[]>({
178	    queryKey: ["api-keys", user?.id],
179	    queryFn: async () => {
180	      if (!user) return [];
181	
182	      const { data, error } = await supabase
183	        .from("api_keys")
184	        .select(
185	          "id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at",
186	        )
187	        .eq("user_id", user.id)
188	        .is("revoked_at", null)
189	        .order("created_at", { ascending: false });
190	
191	      if (error) throw new Error(error.message);
192	      return (data ?? []) as ApiKey[];
193	    },
194	    enabled: !!user,
195	  });
196	}
197	
198	// ── useCreateApiKey ───────────────────────────────────────────
199	// Generates a new API key, hashes it, stores the hash, and returns
200	// the FULL key (shown only once — never stored in plaintext).
201	
202	export interface CreatedApiKey {
203	  fullKey: string;
204	  row: ApiKey;
205	}
206	
207	export function useCreateApiKey() {
208	  const { user } = useAuth();
209	  const queryClient = useQueryClient();
210	
211	  return useMutation<CreatedApiKey, Error, { name: string }>({
212	    mutationFn: async ({ name }) => {
213	      if (!user) throw new Error("Not authenticated");
214	
215	      // Generate key: cs_live_ + 32 hex chars from UUID (no dashes = 32 chars)
216	      const rawUuid = crypto.randomUUID().replace(/-/g, "");
217	      const fullKey = `cs_live_${rawUuid}`;
218	      const keyPrefix = fullKey.slice(0, 12);
219	
220	      const keyHash = await hashApiKey(fullKey);
221	
222	      const { data, error } = await supabase
223	        .from("api_keys")
224	        .insert({
225	          user_id: user.id,
226	          name,
227	          key_hash: keyHash,
228	          key_prefix: keyPrefix,
229	          permissions: ["read", "write"],
230	        })
231	        .select(
232	          "id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at",
233	        )
234	        .single();
235	
236	      if (error) throw new Error(error.message);
237	      if (!data) throw new Error("Failed to create API key.");
238	
239	      return { fullKey, row: data as ApiKey };
240	    },
241	    onSuccess: () => {
242	      queryClient.invalidateQueries({ queryKey: ["api-keys"] });
243	    },
244	    onError: (error) => {
245	      toast.error(error.message || "Failed to create API key.");
246	    },
247	  });
248	}
249	
250	// ── useRevokeApiKey ───────────────────────────────────────────
251	// Sets revoked_at = NOW() on the given key row.
252	
253	export function useRevokeApiKey() {
254	  const queryClient = useQueryClient();
255	
256	  return useMutation<void, Error, { id: string }>({
257	    mutationFn: async ({ id }) => {
258	      const { error } = await supabase
259	        .from("api_keys")
260	        .update({ revoked_at: new Date().toISOString() })
261	        .eq("id", id);
262	
263	      if (error) throw new Error(error.message);
264	    },
265	    onSuccess: () => {
266	      queryClient.invalidateQueries({ queryKey: ["api-keys"] });
267	      toast.success("API key revoked.");
268	    },
269	    onError: (error) => {
270	      toast.error(error.message || "Failed to revoke API key.");
271	    },
272	  });
273	}
