275	=== use-bulk-scan ===
276	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
277	import { toast } from "sonner";
278	import supabase from "@/lib/supabase";
279	import { useAuth } from "@/contexts/AuthContext";
280	import type { BulkScanJob } from "@/types";
281	import type { BulkScanJobRow } from "@/types/database";
282	
283	// ── Query keys ───────────────────────────────────────────────────
284	
285	export const bulkScanKeys = {
286	  all: ["bulk_scan_jobs"] as const,
287	  lists: () => [...bulkScanKeys.all, "list"] as const,
288	  list: (userId: string) => [...bulkScanKeys.lists(), userId] as const,
289	  detail: (id: string) => [...bulkScanKeys.all, "detail", id] as const,
290	};
291	
292	// ── Row → App type mapper ────────────────────────────────────────
293	
294	function rowToJob(row: BulkScanJobRow): BulkScanJob {
295	  return {
