311	/** Normalize a single URL string — prepend https:// if missing */
312	export function normalizeUrl(str: string): string {
313	  const trimmed = str.trim();
314	  if (!trimmed) return trimmed;
315	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
316	  return `https://${trimmed}`;
317	}
318	
319	/** Returns true if the normalized string is a valid http/https URL */
320	export function isValidUrl(str: string): boolean {
321	  try {
322	    const url = new URL(str);
323	    return url.protocol === "https:" || url.protocol === "http:";
324	  } catch {
325	    return false;
326	  }
327	}
