329	export interface ParsedUrlLine {
330	  lineNumber: number;
331	  raw: string;
332	  normalized: string;
333	  valid: boolean;
334	}
335	
336	/** Parse a textarea value into per-line URL results */
337	export function parseUrlLines(raw: string): ParsedUrlLine[] {
338	  return raw
339	    .split("\n")
340	    .map((line, idx) => {
341	      const normalized = normalizeUrl(line);
342	      return {
343	        lineNumber: idx + 1,
344	        raw: line,
345	        normalized,
346	        valid: normalized.length > 0 && isValidUrl(normalized),
347	      };
348	    })
349	    .filter((l) => l.raw.trim().length > 0);
350	}
