818	import { useState, useEffect, useRef } from "react";
819	
820	/**
821	 * Animates a number from 0 to target value.
822	 * Used for KPI card numbers on the dashboard.
823	 */
824	export function useCountUp(target: number, duration: number = 1200): number {
825	  const [value, setValue] = useState(0);
826	  const startTime = useRef<number | null>(null);
827	  const rafId = useRef<number>(0);
828	
829	  useEffect(() => {
830	    startTime.current = null;
831	
832	    const animate = (timestamp: number) => {
833	      if (startTime.current === null) startTime.current = timestamp;
834	      const elapsed = timestamp - startTime.current;
835	      const progress = Math.min(elapsed / duration, 1);
836	
837	      // Ease-out cubic for smooth deceleration
838	      const eased = 1 - Math.pow(1 - progress, 3);
839	      setValue(Math.round(eased * target));
840	
841	      if (progress < 1) {
842	        rafId.current = requestAnimationFrame(animate);
843	      }
844	    };
845	
846	    rafId.current = requestAnimationFrame(animate);
847	
848	    return () => cancelAnimationFrame(rafId.current);
849	  }, [target, duration]);
850	
851	  return value;
852	}
