987	    queryFn: async (): Promise<DashboardData> => {
988	      if (!user?.id) return EMPTY_DASHBOARD;
989	
990	      // Fetch all completed scans for the user
991	      const { data: scansData, error: scansError } = await supabase
992	        .from("scans")
