996	
997	      if (scansError) throw new Error(scansError.message);
998	
999	      const scans = (scansData as ScanRow[]).map(rowToScan);
1000	
1001	      if (scans.length === 0) return EMPTY_DASHBOARD;
1002	
1003	      const completedScans = scans.filter((s) => s.status === "completed" && s.overall_score !== null);
1004	      const recentScans = scans.slice(0, 5);
1005	      const latestScanId = completedScans[0]?.id ?? null;
1006	
1007	      // ── Stats aggregation ─────────────────────────────────────
1008	
1009	      const now = new Date();
1010	      const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
1011	      const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
1012	
1013	      const scansThisMonth = completedScans.filter(
1014	        (s) => new Date(s.created_at) >= monthStart
1015	      );
1016	      const scansLastMonth = completedScans.filter(
1017	        (s) =>
1018	          new Date(s.created_at) >= lastMonthStart &&
1019	          new Date(s.created_at) < monthStart
1020	      );
1021	
1022	      const avgScore =
1023	        completedScans.length > 0
1024	          ? Math.round(
1025	              completedScans.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
1026	                completedScans.length
1027	            )
1028	          : 0;
1029	
1030	      const avgScoreThisMonth =
1031	        scansThisMonth.length > 0
1032	          ? Math.round(
1033	              scansThisMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
1034	                scansThisMonth.length
1035	            )
1036	          : 0;
1037	
1038	      const avgScoreLastMonth =
1039	        scansLastMonth.length > 0
1040	          ? Math.round(
1041	              scansLastMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
1042	                scansLastMonth.length
1043	            )
