1048	      const totalQuickWins = completedScans.reduce((sum, s) => sum + s.quick_wins, 0);
1049	
1050	      const scoreTrendDelta =
1051	        avgScoreLastMonth > 0 ? avgScoreThisMonth - avgScoreLastMonth : 0;
1052	      const scansTrendDelta =
1053	        scansLastMonth.length > 0
1054	          ? Math.round(
1055	              ((scansThisMonth.length - scansLastMonth.length) /
1056	                scansLastMonth.length) *
1057	                100
1058	            )
1059	          : scansThisMonth.length > 0
1060	          ? 100
1061	          : 0;
1062	
1063	      const stats: DashboardStats = {
1064	        total_scans: scansThisMonth.length,
1065	        avg_score: avgScore,
1066	        total_issues: totalIssues,
1067	        critical_issues: totalCritical,
1068	        estimated_revenue_impact: Math.round(totalQuickWins * 125),
1069	        score_trend: scoreTrendDelta,
1070	        scans_trend: scansTrendDelta,
1071	        quick_wins: totalQuickWins,
1072	      };
1073	
1074	      // ── Score Trend (last 4 weeks) ────────────────────────────
1075	
1076	      const fourWeeksAgo = new Date(now.getTime() - 28 * 24 * 60 * 60 * 1000);
1077	      const recentForTrend = completedScans.filter(
1078	        (s) => new Date(s.created_at) >= fourWeeksAgo
1079	      );
1080	
1081	      const weekBuckets = new Map<number, number[]>(); // weekIndex → scores[]
1082	      for (const scan of recentForTrend) {
1083	        const scanDate = new Date(scan.created_at);
1084	        const diffMs = now.getTime() - scanDate.getTime();
1085	        const weekIndex = 3 - Math.min(3, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7)));
1086	        const existing = weekBuckets.get(weekIndex) ?? [];
1087	        if (scan.overall_score !== null) {
1088	          existing.push(scan.overall_score);
1089	          weekBuckets.set(weekIndex, existing);
1090	        }
1091	      }
1092	
1093	      const scoreTrend: ScoreTrendPoint[] = [3, 2, 1, 0].map((weeksAgo, idx) => {
1094	        const label = getWeekLabelForIndex(weeksAgo);
1095	        const scores = weekBuckets.get(idx) ?? [];
1096	        const avg =
1097	          scores.length > 0
1098	            ? Math.round(scores.reduce((s, v) => s + v, 0) / scores.length)
1099	            : 0;
1100	        return { week: label, score: avg };
1101	      }).filter((p) => p.score > 0);
1102	
1103	      // ── Score Distribution ────────────────────────────────────
1104	
1105	      const RANGES = ["0-20", "21-40", "41-60", "61-80", "81-100"];
1106	      const distributionMap = new Map<string, number>(RANGES.map((r) => [r, 0]));
1107	
1108	      for (const scan of completedScans) {
1109	        if (scan.overall_score !== null) {
1110	          const bucket = scoreToRange(scan.overall_score);
1111	          distributionMap.set(bucket, (distributionMap.get(bucket) ?? 0) + 1);
1112	        }
1113	      }
1114	
1115	      const scoreDistribution: ScoreDistributionBucket[] = RANGES.map((range) => ({
1116	        range,
1117	        count: distributionMap.get(range) ?? 0,
1118	        fill: getBucketFill(range),
1119	      }));
1120	
1121	      // ── Top Quick Wins from latest completed scan ─────────────
1122	
1123	      let topQuickWins: (Finding & { pillar: string })[] = [];
1124	
1125	      if (latestScanId) {
1126	        const { data: resultsData } = await supabase
1127	          .from("scan_results")
1128	          .select("*")
1129	          .eq("scan_id", latestScanId);
1130	
1131	        if (resultsData && resultsData.length > 0) {
1132	          const allFindings: (Finding & { pillar: string })[] = (
1133	            resultsData as ScanResultRow[]
1134	          ).flatMap((r) =>
1135	            (r.findings ?? [])
1136	              .filter((f: DbFinding) => f.severity !== "passed" && f.effort === "quick")
1137	              .map((f: DbFinding) => ({
1138	                id: f.id,
1139	                title: f.title,
1140	                severity: f.severity,
1141	                current_state: f.current_state,
1142	                recommendation: f.recommendation,
1143	                ai_suggestion: f.ai_suggestion,
1144	                is_premium: f.is_premium,
1145	                effort: f.effort,
1146	                estimated_lift: f.estimated_lift,
1147	                category: f.category,
1148	                pillar: r.pillar,
1149	              }))
1150	          );
1151	
1152	          topQuickWins = allFindings
1153	            .sort((a, b) => {
1154	              const liftA = parseFloat(a.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
1155	              const liftB = parseFloat(b.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
