1165	        completedScans.length > 0
1166	          ? Math.max(...completedScans.map((s) => s.overall_score ?? 0))
1167	          : 0;
1168	
1169	      const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
1170	      const scansThisWeek = scans.filter(
1171	        (s) => new Date(s.created_at) >= oneWeekAgo
1172	      ).length;
1173	
1174	      // ── score_trend_data: weekly averages for last 8 weeks ────
1175	
1176	      const eightWeeksAgo = new Date(now.getTime() - 56 * 24 * 60 * 60 * 1000);
1177	      const scansForTrend = completedScans.filter(
1178	        (s) => new Date(s.created_at) >= eightWeeksAgo
1179	      );
1180	
1181	      const weekBuckets8 = new Map<number, number[]>();
1182	      for (const scan of scansForTrend) {
1183	        const diffMs = now.getTime() - new Date(scan.created_at).getTime();
1184	        const weekIdx = 7 - Math.min(7, Math.floor(diffMs / (7 * 24 * 60 * 60 * 1000)));
1185	        const existing = weekBuckets8.get(weekIdx) ?? [];
1186	        if (scan.overall_score !== null) {
1187	          existing.push(scan.overall_score);
1188	          weekBuckets8.set(weekIdx, existing);
1189	        }
1190	      }
1191	
1192	      const scoreTrendData: Array<{ date: string; score: number }> = Array.from(
1193	        { length: 8 },
1194	        (_, i) => {
1195	          const d = new Date(now.getTime() - (7 - i) * 7 * 24 * 60 * 60 * 1000);
1196	          const label = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
1197	          const scores = weekBuckets8.get(i) ?? [];
1198	          const avg =
1199	            scores.length > 0

1200	              ? Math.round(scores.reduce((s, v) => s + v, 0) / scores.length)
1201	              : 0;
1202	          return { date: label, score: avg };
1203	        }
1204	      ).filter((p) => p.score > 0);
1205	
1206	      // ── critical_action_items: top 3 from recent completed scans
1207	
1208	      let criticalActionItems: CriticalActionItem[] = [];
1209	
1210	      const recentCompletedIds = completedScans.slice(0, 3).map((s) => s.id);
1211	      if (recentCompletedIds.length > 0) {
1212	        const { data: actionResultsData } = await supabase
1213	          .from("scan_results")
1214	          .select("scan_id, findings")
1215	          .in("scan_id", recentCompletedIds);
1216	
1217	        if (actionResultsData && actionResultsData.length > 0) {
