1263	=== use-debounce ===
1264	import { useState, useEffect } from "react";
1265	
1266	export function useDebounce<T>(value: T, delay = 300): T {
1267	  const [debounced, setDebounced] = useState<T>(value);
1268	  useEffect(() => {
1269	    const t = setTimeout(() => setDebounced(value), delay);
1270	    return () => clearTimeout(t);
1271	  }, [value, delay]);
1272	  return debounced;
1273	}
