1282	import { useQuery } from "@tanstack/react-query";
1283	import supabase from "@/lib/supabase";
1284	import { FLAG_DEFINITIONS } from "@/hooks/admin/use-feature-flags";
1285	
1286	const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
1287	  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
1288	);
1289	
1290	async function fetchAllFeatureFlags(): Promise<Record<string, boolean>> {
1291	  const { data, error } = await supabase
1292	    .from("system_config")
1293	    .select("value")
1294	    .eq("key", "feature_flags")
1295	    .single();
1296	
1297	  if (error && error.code !== "PGRST116") {
1298	    // On error, return defaults silently — never break app for missing config
1299	    return DEFAULT_FLAGS;
1300	  }
1301	
1302	  const stored = (data?.value ?? {}) as Record<string, boolean>;
1303	  return { ...DEFAULT_FLAGS, ...stored };
1304	}
