1306	/**
1307	 * Returns the boolean value of a single feature flag.
1308	 * Falls back to `defaultValue` if the flag is not set or loading.
1309	 */
1310	export function useFeatureFlag(key: string, defaultValue = true): boolean {
1311	  const { data } = useQuery({
1312	    queryKey: ["feature-flags"],
1313	    queryFn: fetchAllFeatureFlags,
1314	    staleTime: 5 * 60 * 1000, // 5 minutes
1315	    // Never throw on error — silently use defaults
1316	    retry: 1,
1317	  });
1318	
1319	  if (data === undefined) {
1320	    // Still loading — return the flag's defined default or the passed default
1321	    const flagDef = FLAG_DEFINITIONS.find((f) => f.key === key);
1322	    return flagDef?.defaultValue ?? defaultValue;
1323	  }
1324	
1325	  return data[key] ?? defaultValue;
1326	}
