2185	// ── Types ────────────────────────────────────────────────────────
2186	
2187	export interface PillarDelta {
2188	  pillar: CroPillar;
2189	  previous: number;
2190	  current: number;
2191	  delta: number;
2192	}
2193	
2194	export interface ScanComparison {
2195	  hasPrevious: boolean;
2196	  previousScore: number;
2197	  currentScore: number;
2198	  scoreDelta: number;
2199	  pillarDeltas: PillarDelta[];
2200	  previousScanId: string;
2201	}
2202	
2203	const EMPTY_COMPARISON: ScanComparison = {
2204	  hasPrevious: false,
2205	  previousScore: 0,
2206	  currentScore: 0,
2207	  scoreDelta: 0,
2208	  pillarDeltas: [],
2209	  previousScanId: "",
2210	};
2211	
2212	// ── Query keys ──────────────────────────────────────────────────
2213	
2214	export const scanComparisonKeys = {
2215	  comparison: (scanId: string) => ["scan-comparison", scanId] as const,
2216	};
2217	
2218	// ── useScanComparison ────────────────────────────────────────────
2219	// For the current scan, find the previous scan for the same URL and
2220	// compute per-pillar deltas.
2221	
2222	export function useScanComparison(
2223	  scanId: string | undefined,
2224	  url: string | undefined,
2225	) {
2226	  const { user } = useAuth();
2227	
2228	  return useQuery({
2229	    queryKey: scanComparisonKeys.comparison(scanId ?? ""),
2230	    queryFn: async (): Promise<ScanComparison> => {
2231	      if (!scanId || !url || !user?.id) return EMPTY_COMPARISON;
2232	
2233	      const urlHash = url.toLowerCase().trim();
2234	
2235	      // 1. Find all history entries for this URL, ordered ASC
2236	      const { data: historyRows, error: historyError } = await supabase
2237	        .from("scan_history")
2238	        .select("scan_id, score, scanned_at")
2239	        .eq("user_id", user.id)
2240	        .eq("url_hash", urlHash)
2241	        .order("scanned_at", { ascending: true });
2242	
2243	      if (historyError || !historyRows || historyRows.length < 2) {
2244	        return EMPTY_COMPARISON;
2245	      }
2246	
2247	      // 2. Find this scan's position in history
2248	      const currentIndex = (historyRows as Array<{ scan_id: string; score: number; scanned_at: string }>)
2249	        .findIndex((r) => r.scan_id === scanId);
2250	
2251	      if (currentIndex <= 0) {
2252	        // Not found or is the first entry — no previous scan
2253	        return EMPTY_COMPARISON;
2254	      }
2255	
2256	      const currentEntry = historyRows[currentIndex] as { scan_id: string; score: number };
2257	      const previousEntry = historyRows[currentIndex - 1] as { scan_id: string; score: number };
2258	
2259	      // 3. Fetch pillar results for previous scan
2260	      const { data: prevResults, error: prevError } = await supabase
2261	        .from("scan_results")
2262	        .select("pillar, score")
2263	        .eq("scan_id", previousEntry.scan_id);
2264	
2265	      if (prevError || !prevResults) return EMPTY_COMPARISON;
2266	
2267	      // 4. Fetch pillar results for current scan
2268	      const { data: currResults, error: currError } = await supabase
2269	        .from("scan_results")
2270	        .select("pillar, score")
2271	        .eq("scan_id", scanId);
2272	
2273	      if (currError || !currResults) return EMPTY_COMPARISON;
2274	
2275	      // 5. Build per-pillar deltas
2276	      const prevMap = new Map<string, number>();
2277	      for (const r of prevResults as Pick<ScanResultRow, "pillar" | "score">[]) {
2278	        prevMap.set(r.pillar, r.score);
2279	      }
2280	
2281	      const pillarDeltas: PillarDelta[] = [];
2282	      for (const r of currResults as Pick<ScanResultRow, "pillar" | "score">[]) {
2283	        const prevScore = prevMap.get(r.pillar);
2284	        if (prevScore !== undefined) {
2285	          pillarDeltas.push({
2286	            pillar: r.pillar as CroPillar,
2287	            previous: prevScore,
2288	            current: r.score,
2289	            delta: r.score - prevScore,
2290	          });
2291	        }
2292	      }
2293	
2294	      return {
2295	        hasPrevious: true,
2296	        previousScore: previousEntry.score,
2297	        currentScore: currentEntry.score,
2298	        scoreDelta: currentEntry.score - previousEntry.score,
2299	        pillarDeltas,
2300	        previousScanId: previousEntry.scan_id,
2301	      };
2302	    },
2303	    enabled: !!scanId && !!url && !!user?.id,
2304	    staleTime: 1000 * 60 * 5,
2305	  });
2306	}
