2363	// ── UrlHistoryGroup ─────────────────────────────────────────────
2364	
2365	export interface UrlHistoryGroup {
2366	  url: string;
2367	  url_hash: string;
2368	  entries: ScanHistoryEntry[];
2369	  latestScore: number;
2370	  firstScore: number;
2371	  delta: number;
2372	  latestScanId: string;
2373	}
