2375	// ── useAllUrlHistory ────────────────────────────────────────────
2376	// Returns all tracked URLs for the current user, grouped, with deltas.
2377	
2378	export function useAllUrlHistory() {
2379	  const { user } = useAuth();
2380	
2381	  return useQuery({
2382	    queryKey: scanHistoryKeys.allUrls(user?.id ?? ""),
2383	    queryFn: async (): Promise<UrlHistoryGroup[]> => {
2384	      if (!user?.id) return [];
2385	
2386	      const { data, error } = await supabase
2387	        .from("scan_history")
2388	        .select("*")
2389	        .eq("user_id", user.id)
2390	        .order("scanned_at", { ascending: true });
2391	
2392	      if (error) throw new Error(error.message);
2393	
2394	      const rows = (data as Record<string, unknown>[]).map(rowToEntry);
2395	
2396	      // Group by url_hash
2397	      const groupMap = new Map<string, ScanHistoryEntry[]>();
2398	      for (const entry of rows) {
2399	        const existing = groupMap.get(entry.url_hash);
2400	        if (existing) {
2401	          existing.push(entry);
2402	        } else {
2403	          groupMap.set(entry.url_hash, [entry]);
2404	        }
2405	      }
2406	
2407	      const groups: UrlHistoryGroup[] = [];
2408	      for (const [urlHash, entries] of groupMap) {
2409	        // entries are already ASC by scanned_at
2410	        const firstEntry = entries[0];
2411	        const lastEntry = entries[entries.length - 1];
2412	        groups.push({
2413	          url: lastEntry.url,
2414	          url_hash: urlHash,
2415	          entries,
2416	          latestScore: lastEntry.score,
2417	          firstScore: firstEntry.score,
2418	          delta: lastEntry.score - firstEntry.score,
2419	          latestScanId: lastEntry.scan_id,
2420	        });
2421	      }
2422	
2423	      // Sort groups by latest scan time DESC
2424	      groups.sort((a, b) => {
2425	        const aLast = a.entries[a.entries.length - 1].scanned_at;
2426	        const bLast = b.entries[b.entries.length - 1].scanned_at;
2427	        return bLast.localeCompare(aLast);
2428	      });
2429	
2430	      return groups;
2431	    },
2432	    enabled: !!user?.id,
2433	    staleTime: 1000 * 60 * 2,
2434	  });
2435	}
