3113	import * as React from "react";
3114	
3115	import type { ToastActionElement, ToastProps } from "@/components/ui/toast";
3116	
3117	const TOAST_LIMIT = 1;
3118	const TOAST_REMOVE_DELAY = 1000000;
3119	
3120	type ToasterToast = ToastProps & {
3121	  id: string;
3122	  title?: React.ReactNode;
3123	  description?: React.ReactNode;
3124	  action?: ToastActionElement;
3125	};
3126	
3127	const actionTypes = {
3128	  ADD_TOAST: "ADD_TOAST",
3129	  UPDATE_TOAST: "UPDATE_TOAST",
3130	  DISMISS_TOAST: "DISMISS_TOAST",
3131	  REMOVE_TOAST: "REMOVE_TOAST",
3132	} as const;
3133	
3134	let count = 0;
3135	
3136	function genId() {
3137	  count = (count + 1) % Number.MAX_SAFE_INTEGER;
3138	  return count.toString();
3139	}
3140	
3141	type ActionType = typeof actionTypes;
3142	
3143	type Action =
3144	  | {
3145	      type: ActionType["ADD_TOAST"];
3146	      toast: ToasterToast;
3147	    }
3148	  | {
3149	      type: ActionType["UPDATE_TOAST"];
3150	      toast: Partial<ToasterToast>;
3151	    }
3152	  | {
3153	      type: ActionType["DISMISS_TOAST"];
3154	      toastId?: ToasterToast["id"];
3155	    }
3156	  | {
3157	      type: ActionType["REMOVE_TOAST"];
3158	      toastId?: ToasterToast["id"];
3159	    };
3160	
3161	interface State {
3162	  toasts: ToasterToast[];
3163	}
3164	
3165	const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();
3166	
3167	const addToRemoveQueue = (toastId: string) => {
3168	  if (toastTimeouts.has(toastId)) {
3169	    return;
3170	  }
3171	
3172	  const timeout = setTimeout(() => {
3173	    toastTimeouts.delete(toastId);
3174	    dispatch({
3175	      type: "REMOVE_TOAST",
3176	      toastId: toastId,
3177	    });
3178	  }, TOAST_REMOVE_DELAY);
3179	
3180	  toastTimeouts.set(toastId, timeout);
3181	};
3182	
3183	export const reducer = (state: State, action: Action): State => {
3184	  switch (action.type) {
3185	    case "ADD_TOAST":
3186	      return {
3187	        ...state,
3188	        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
3189	      };
3190	
3191	    case "UPDATE_TOAST":
3192	      return {
3193	        ...state,
3194	        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
3195	      };
3196	
3197	    case "DISMISS_TOAST": {
3198	      const { toastId } = action;
3199	
3200	      // ! Side effects ! - This could be extracted into a dismissToast() action,
3201	      // but I'll keep it here for simplicity
3202	      if (toastId) {
3203	        addToRemoveQueue(toastId);
3204	      } else {
3205	        state.toasts.forEach((toast) => {
3206	          addToRemoveQueue(toast.id);
3207	        });
3208	      }
3209	
3210	      return {
3211	        ...state,
3212	        toasts: state.toasts.map((t) =>
3213	          t.id === toastId || toastId === undefined
3214	            ? {
3215	                ...t,
3216	                open: false,
3217	              }
3218	            : t,
3219	        ),
3220	      };
3221	    }
3222	    case "REMOVE_TOAST":
3223	      if (action.toastId === undefined) {
3224	        return {
3225	          ...state,
3226	          toasts: [],
3227	        };
3228	      }
3229	      return {
3230	        ...state,
3231	        toasts: state.toasts.filter((t) => t.id !== action.toastId),
3232	      };
3233	  }
3234	};
3235	
3236	const listeners: Array<(state: State) => void> = [];
3237	
3238	let memoryState: State = { toasts: [] };
3239	
3240	function dispatch(action: Action) {
3241	  memoryState = reducer(memoryState, action);
3242	  listeners.forEach((listener) => {
3243	    listener(memoryState);
3244	  });
3245	}
3246	
3247	type Toast = Omit<ToasterToast, "id">;
3248	
3249	function toast({ ...props }: Toast) {
3250	  const id = genId();
3251	
3252	  const update = (props: ToasterToast) =>
3253	    dispatch({
3254	      type: "UPDATE_TOAST",
3255	      toast: { ...props, id },
3256	    });
3257	  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });
3258	
3259	  dispatch({
3260	    type: "ADD_TOAST",
3261	    toast: {
3262	      ...props,
3263	      id,
3264	      open: true,
3265	      onOpenChange: (open) => {
3266	        if (!open) dismiss();
3267	      },
3268	    },
3269	  });
3270	
3271	  return {
3272	    id: id,
3273	    dismiss,
3274	    update,
3275	  };
3276	}
3277	
3278	function useToast() {
3279	  const [state, setState] = React.useState<State>(memoryState);
3280	
3281	  React.useEffect(() => {
3282	    listeners.push(setState);
3283	    return () => {
3284	      const index = listeners.indexOf(setState);
3285	      if (index > -1) {
3286	        listeners.splice(index, 1);
3287	      }
3288	    };
3289	  }, [state]);
3290	
3291	  return {
3292	    ...state,
3293	    toast,
3294	    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
3295	  };
3296	}
3297	
3298	export { useToast, toast };
