669	/** Generate a stable teaser score 45–72 for an unauthenticated guest scan */
670	function generateTeaserScore(url: string): number {
671	  let hash = 0;
672	  for (let i = 0; i < url.length; i++) {
673	    hash = (hash * 31 + url.charCodeAt(i)) & 0xffffffff;
674	  }
675	  return 45 + (Math.abs(hash) % 28);
676	}
