678	/** Basic URL validation — checks structure, not reachability */
679	function isValidUrl(str: string): boolean {
680	  try {
681	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
682	    return url.protocol === "https:" || url.protocol === "http:";
683	  } catch {
684	    return false;
685	  }
686	}
