688	/** Normalize URL: prepend https:// if missing */
689	function normalizeUrl(str: string): string {
690	  const trimmed = str.trim();
691	  if (!trimmed) return trimmed;
692	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
693	  return `https://${trimmed}`;
694	}
