'use client';

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { Scan, PageType } from "@/types";
import type { ScanRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const scanKeys = {
  all: ["scans"] as const,
  lists: () => [...scanKeys.all, "list"] as const,
  list: (userId: string) => [...scanKeys.lists(), userId] as const,
  teamList: (teamId: string) => [...scanKeys.all, "team", teamId] as const,
  details: () => [...scanKeys.all, "detail"] as const,
  detail: (id: string) => [...scanKeys.details(), id] as const,
};

// ── Row → App type mapper ───────────────────────────────────────

function rowToScan(row: ScanRow): Scan {
  return {
    id: row.id,
    user_id: row.user_id,
    url: row.url,
    favicon_url: row.favicon_url,
    page_title: row.page_title,
    page_type: row.page_type,
    status: row.status,
    overall_score: row.overall_score,
    issues_found: row.issues_found,
    critical_issues: row.critical_issues,
    warnings: row.warnings,
    quick_wins: row.quick_wins,
    screenshot_url: row.screenshot_url,
    device: row.device,
    team_id: row.team_id,
    share_token: row.share_token,
    is_public: row.is_public,
    created_at: row.created_at,
    completed_at: row.completed_at,
  };
}

// ── useScans ────────────────────────────────────────────────────

export function useScans() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Scan[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as ScanRow[]).map(rowToScan);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30,
  });
}

// ── useScan ─────────────────────────────────────────────────────

export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.detail(id ?? ""),
    queryFn: async (): Promise<Scan | null> => {
      if (!id || !user?.id) return null;

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("id", id)
        .eq("user_id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToScan(data as ScanRow);
    },
    enabled: !!id && !!user?.id,
    refetchInterval: options?.refetchInterval,
    staleTime: 0,
  });
}

// ── useCreateScan ───────────────────────────────────────────────

interface CreateScanInput {
  url: string;
  page_type: PageType;
  team_id?: string | null;
}

export function useCreateScan() {
  const supabase = createClient();
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ url, page_type, team_id }: CreateScanInput): Promise<Scan> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { data: scanData, error: insertError } = await supabase
        .from("scans")
        .insert({
          user_id: user.id,
          url,
          page_type,
          status: "pending" as const,
          ...(team_id ? { team_id } : {}),
        })
        .select("*")
        .single();

      if (insertError) throw new Error(insertError.message);

      const scan = rowToScan(scanData as ScanRow);

      supabase.functions
        .invoke("analyze-url", {
          body: { scan_id: scan.id, url, page_type },
        })
        .catch((err: unknown) => {
          console.error("Edge function invocation failed:", err);
          toast.error("Analysis engine failed to start. Please try re-scanning in a moment.", { duration: 6000 });
        });

      return scan;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? [data, ...prev] : [data]
      );
      queryClient.setQueryData(scanKeys.detail(data.id), data);
      refreshProfile();
    },
  });
}

// ── useDeleteScan ───────────────────────────────────────────────

export function useDeleteScan() {
  const supabase = createClient();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("scans")
        .delete()
        .eq("id", scanId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, scanId) => {
      if (!user?.id) return;
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? prev.filter((s) => s.id !== scanId) : []
      );
      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
    },
  });
}

// ── useRefreshScan ──────────────────────────────────────────────

export function useRefreshScan() {
  const createScan = useCreateScan();

  return useMutation({
    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
    },
  });
}

// ── useTeamScans ────────────────────────────────────────────────

export function useTeamScans(teamId: string | undefined) {
  const supabase = createClient();

  return useQuery({
    queryKey: scanKeys.teamList(teamId ?? ""),
    queryFn: async (): Promise<Scan[]> => {
      if (!teamId) return [];

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as ScanRow[]).map(rowToScan);
    },
    enabled: !!teamId,
    staleTime: 1000 * 30,
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { PillarResult, Finding } from "@/types";
import type { ScanResultRow, DbFinding } from "@/types/database";

export const scanResultKeys = {
  all: ["scan-results"] as const,
  byScan: (scanId: string) => ["scan-results", scanId] as const,
};

function dbFindingToFinding(f: DbFinding): Finding {
  return {
    id: f.id,
    title: f.title,
    severity: f.severity,
    current_state: f.current_state,
    recommendation: f.recommendation,
    ai_suggestion: f.ai_suggestion,
    is_premium: f.is_premium,
    effort: f.effort,
    estimated_lift: f.estimated_lift,
    category: f.category,
  };
}

function rowToPillarResult(row: ScanResultRow): PillarResult {
  return {
    id: row.id,
    scan_id: row.scan_id,
    pillar: row.pillar,
    score: row.score,
    weight: row.weight,
    benchmark: row.benchmark,
    findings: (row.findings ?? []).map(dbFindingToFinding),
  };
}

export function useScanResults(scanId: string | undefined) {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanResultKeys.byScan(scanId ?? ""),
    queryFn: async (): Promise<PillarResult[]> => {
      if (!scanId || !user?.id) return [];

      const { data, error } = await supabase
        .from("scan_results")
        .select("*")
        .eq("scan_id", scanId);

      if (error) throw new Error(error.message);
      return (data as ScanResultRow[]).map(rowToPillarResult);
    },
    enabled: !!scanId && !!user?.id,
    staleTime: 1000 * 60 * 5,
  });
}

'use client';

import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { PlanType } from "@/types";

export function useCheckout() {
  const supabase = createClient();

  return useMutation({
    mutationFn: async ({
      plan,
      billingCycle,
    }: {
      plan: Exclude<PlanType, "free">;
      billingCycle: "monthly" | "annual";
    }) => {
      const { data, error } = await supabase.functions.invoke("dodo-checkout", {
        body: { plan, billing_cycle: billingCycle },
      });

      if (error) {
        throw new Error(error.message || "Failed to start checkout. Please try again.");
      }

      if (!data?.url) {
        throw new Error("No checkout URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message = error instanceof Error ? error.message : "Checkout failed.";
      toast.error(message);
    },
  });
}

export function useCustomerPortal() {
  const supabase = createClient();

  return useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("dodo-portal");

      if (error) {
        throw new Error(error.message || "Failed to open billing portal. Please try again.");
      }

      if (!data?.url) {
        throw new Error("No portal URL returned from server.");
      }

      return data.url as string;
    },
    onSuccess: (url) => {
      window.location.href = url;
    },
    onError: (error: unknown) => {
      const message = error instanceof Error ? error.message : "Failed to open portal.";
      toast.error(message);
    },
  });
}

export function useUsage() {
  const { profile } = useAuth();

  if (!profile) {
    return {
      scansUsed: 0,
      scanLimit: 0,
      usagePercent: 0,
      plan: "free" as PlanType,
      billingCycleEnd: null as string | null,
    };
  }

  const usagePercent =
    profile.scan_limit > 0
      ? Math.min((profile.scans_used / profile.scan_limit) * 100, 100)
      : 0;

  return {
    scansUsed: profile.scans_used,
    scanLimit: profile.scan_limit,
    usagePercent,
    plan: profile.plan,
    billingCycleEnd: profile.billing_cycle_end ?? null,
  };
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { AnalyticsMetrics } from "@/types/index";
import { useIntegrations } from "./use-integrations";

export const analyticsKeys = {
  all: ["analytics"] as const,
  byUrl: (url: string) => ["analytics", url] as const,
};

interface AnalyticsNotConnected {
  connected: false;
}

interface AnalyticsSetupRequired {
  connected: true;
  setup_required: true;
}

interface AnalyticsError {
  connected: true;
  error: string;
}

interface AnalyticsSuccess {
  connected: true;
  metrics: AnalyticsMetrics;
}

type FetchAnalyticsResponse =
  | AnalyticsNotConnected
  | AnalyticsSetupRequired
  | AnalyticsError
  | AnalyticsSuccess;

export function useGa4Connection(): { isConnected: boolean; isLoading: boolean } {
  const { data: integrations = [], isLoading } = useIntegrations();
  const isConnected = integrations.some((i) => i.provider === "google_analytics" && i.is_active);
  return { isConnected, isLoading };
}

export function useAnalyticsData(url: string): {
  data: AnalyticsMetrics | null;
  isLoading: boolean;
  isError: boolean;
  setupRequired: boolean;
  errorMessage: string | null;
  notConnected: boolean;
} {
  const supabase = createClient();
  const { isConnected } = useGa4Connection();

  const query = useQuery({
    queryKey: analyticsKeys.byUrl(url),
    queryFn: async (): Promise<FetchAnalyticsResponse> => {
      const { data, error } = await supabase.functions.invoke<FetchAnalyticsResponse>(
        "fetch-analytics",
        { body: { url } },
      );

      if (error) throw new Error(error.message);
      if (!data) throw new Error("Empty response from fetch-analytics");
      return data;
    },
    enabled: isConnected && url.length > 0,
    staleTime: 1000 * 60 * 5,
    retry: 1,
  });

  const response = query.data;

  if (!response) {
    return {
      data: null,
      isLoading: query.isLoading,
      isError: query.isError,
      setupRequired: false,
      errorMessage: null,
      notConnected: !isConnected,
    };
  }

  if (!response.connected) {
    return { data: null, isLoading: false, isError: false, setupRequired: false, errorMessage: null, notConnected: true };
  }

  if ("setup_required" in response && response.setup_required) {
    return { data: null, isLoading: false, isError: false, setupRequired: true, errorMessage: null, notConnected: false };
  }

  if ("error" in response && response.error) {
    return { data: null, isLoading: false, isError: true, setupRequired: false, errorMessage: response.error, notConnected: false };
  }

  if ("metrics" in response && response.metrics) {
    return { data: response.metrics, isLoading: false, isError: false, setupRequired: false, errorMessage: null, notConnected: false };
  }

  return { data: null, isLoading: false, isError: false, setupRequired: false, errorMessage: null, notConnected: false };
}

'use client';

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { ApiKey } from "@/types";

async function hashApiKey(key: string): Promise<string> {
  const encoded = new TextEncoder().encode(key);
  const hashBuffer = await crypto.subtle.digest("SHA-256", encoded);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function useApiKeys() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery<ApiKey[]>({
    queryKey: ["api-keys", user?.id],
    queryFn: async () => {
      if (!user) return [];

      const { data, error } = await supabase
        .from("api_keys")
        .select("id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at")
        .eq("user_id", user.id)
        .is("revoked_at", null)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data ?? []) as ApiKey[];
    },
    enabled: !!user,
  });
}

export interface CreatedApiKey {
  fullKey: string;
  row: ApiKey;
}

export function useCreateApiKey() {
  const supabase = createClient();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation<CreatedApiKey, Error, { name: string }>({
    mutationFn: async ({ name }) => {
      if (!user) throw new Error("Not authenticated");

      const rawUuid = crypto.randomUUID().replace(/-/g, "");
      const fullKey = `cs_live_${rawUuid}`;
      const keyPrefix = fullKey.slice(0, 12);
      const keyHash = await hashApiKey(fullKey);

      const { data, error } = await supabase
        .from("api_keys")
        .insert({
          user_id: user.id,
          name,
          key_hash: keyHash,
          key_prefix: keyPrefix,
          permissions: ["read", "write"],
        })
        .select("id, user_id, team_id, name, key_prefix, permissions, rate_limit, last_used_at, created_at, revoked_at")
        .single();

      if (error) throw new Error(error.message);
      if (!data) throw new Error("Failed to create API key.");

      return { fullKey, row: data as ApiKey };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["api-keys"] });
    },
    onError: (error) => {
      toast.error(error.message || "Failed to create API key.");
    },
  });
}

export function useRevokeApiKey() {
  const supabase = createClient();
  const queryClient = useQueryClient();

  return useMutation<void, Error, { id: string }>({
    mutationFn: async ({ id }) => {
      const { error } = await supabase
