export const bulkScanKeys = {
  all: ["bulk_scan_jobs"] as const,
  lists: () => [...bulkScanKeys.all, "list"] as const,
  list: (userId: string) => [...bulkScanKeys.lists(), userId] as const,
  detail: (id: string) => [...bulkScanKeys.all, "detail", id] as const,
};

function rowToJob(row: BulkScanJobRow): BulkScanJob {
  return {
    id: row.id,
    user_id: row.user_id,
    team_id: row.team_id,
    status: row.status,
    urls: row.urls,
    page_type: row.page_type,
    total: row.total,
    completed: row.completed,
    failed: row.failed,
    created_at: row.created_at,
  };
}

export function normalizeUrl(str: string): string {
  const trimmed = str.trim();
  if (!trimmed) return trimmed;
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  return `https://${trimmed}`;
}

export function isValidUrl(str: string): boolean {
  try {
    const url = new URL(str);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

export interface ParsedUrlLine {
  lineNumber: number;
  raw: string;
  normalized: string;
  valid: boolean;
}

export function parseUrlLines(raw: string): ParsedUrlLine[] {
  return raw
    .split("\n")
    .map((line, idx) => {
      const normalized = normalizeUrl(line);
      return {
        lineNumber: idx + 1,
        raw: line,
        normalized,
        valid: normalized.length > 0 && isValidUrl(normalized),
      };
    })
    .filter((l) => l.raw.trim().length > 0);
}

export function useBulkScanJobs() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: bulkScanKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<BulkScanJob[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as BulkScanJobRow[]).map(rowToJob);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30,
  });
}

export function useBulkScanJob(jobId: string | undefined) {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: bulkScanKeys.detail(jobId ?? ""),
    queryFn: async (): Promise<BulkScanJob | null> => {
      if (!jobId || !user?.id) return null;

      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .select("*")
        .eq("id", jobId)
        .eq("user_id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToJob(data as BulkScanJobRow);
    },
    enabled: !!jobId && !!user?.id,
    refetchInterval: (query) => {
      const job = query.state.data;
      if (!job) return false;
      return job.status === "pending" || job.status === "processing" ? 2000 : false;
    },
    staleTime: 0,
  });
}

interface CreateBulkScanInput {
  urls: string[];
  page_type: string;
  team_id?: string | null;
}

export function useCreateBulkScan() {
  const supabase = createClient();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ urls, page_type, team_id }: CreateBulkScanInput): Promise<BulkScanJob> => {
      if (!user?.id) throw new Error("Not authenticated");

      const invalid = urls.filter((u) => !isValidUrl(normalizeUrl(u)));
      if (invalid.length > 0) {
        throw new Error(`${invalid.length} invalid URL(s) detected. Please fix them before submitting.`);
      }

      const normalizedUrls = urls.map(normalizeUrl);

      const { data, error } = await supabase
        .from("bulk_scan_jobs")
        .insert({
          user_id: user.id,
          team_id: team_id ?? null,
          status: "pending" as const,
          urls: normalizedUrls,
          page_type,
          total: normalizedUrls.length,
          completed: 0,
          failed: 0,
        })
        .select("*")
        .single();

      if (error) throw new Error(error.message);

      const job = rowToJob(data as BulkScanJobRow);

      supabase.functions
        .invoke("bulk-scan", { body: { job_id: job.id } })
        .catch((err: unknown) => {
          console.error("Bulk scan edge function invocation failed:", err);
          toast.error("Bulk scan engine failed to start. Please try again.", { duration: 6000 });
        });

      return job;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      queryClient.setQueryData<BulkScanJob[]>(bulkScanKeys.list(user.id), (prev) =>
        prev ? [data, ...prev] : [data]
      );
      queryClient.setQueryData(bulkScanKeys.detail(data.id), data);
    },
  });
}

export function useCancelBulkScan() {
  const supabase = createClient();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (jobId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("bulk_scan_jobs")
        .update({ status: "failed" })
        .eq("id", jobId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, jobId) => {
      if (!user?.id) return;
      queryClient.setQueryData<BulkScanJob>(bulkScanKeys.detail(jobId), (prev) =>
        prev ? { ...prev, status: "failed" } : prev
      );
      queryClient.setQueryData<BulkScanJob[]>(bulkScanKeys.list(user.id), (prev) =>
        prev ? prev.map((j) => (j.id === jobId ? { ...j, status: "failed" } : j)) : prev
      );
      toast.success("Bulk scan cancelled.");
    },
    onError: (err: unknown) => {
      const message = err instanceof Error ? err.message : "Failed to cancel job";
      toast.error(message);
    },
  });
}

