export function useCreateCompetitorGroup() {
  const supabase = createClient();
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateGroupInput): Promise<CompetitorGroupWithUrls> => {
      if (!user?.id) throw new Error("Not authenticated");

      const groupInsert: CompetitorGroupInsert = {
        user_id: user.id,
        primary_url: input.primary_url,
        name: input.name,
      };

      const { data: groupData, error: groupError } = await supabase
        .from("competitor_groups")
        .insert(groupInsert)
        .select("*")
        .single();

      if (groupError) throw new Error(groupError.message);
      const group = groupData as CompetitorGroupRow;

      const allUrls = [input.primary_url, ...input.competitor_urls];
      const urlRows = allUrls.map((url) => ({ group_id: group.id, url }));

      const { data: urlData, error: urlError } = await supabase
        .from("competitor_urls")
        .insert(urlRows)
        .select("*");

      if (urlError) throw new Error(urlError.message);

      return rowToGroup({ ...group, competitor_urls: urlData as CompetitorUrlRow[] });
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      queryClient.setQueryData<CompetitorGroupWithUrls[]>(
        competitorKeys.list(user.id),
        (prev) => (prev ? [data, ...prev] : [data])
