  industries: ["industry-benchmarks", "distinct-industries"] as const,
};

export interface PillarBenchmark {
  avg_score: number;
  sample_size: number;
}

export function useIndustryBenchmarks(industry: IndustryType, pageType: string) {
  const supabase = createClient();

  return useQuery({
    queryKey: benchmarkKeys.byIndustryAndPage(industry, pageType),
    queryFn: async (): Promise<Record<CroPillar, PillarBenchmark>> => {
      const { data, error } = await supabase
        .from("industry_benchmarks")
        .select("*")
        .eq("industry", industry)
        .eq("page_type", pageType);

      if (error) throw new Error(error.message);

