export const profileKeys = {
  all: ["profile"] as const,
  byUser: (userId: string) => ["profile", userId] as const,
};

export function useProfile() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: profileKeys.byUser(user?.id ?? ""),
    queryFn: async (): Promise<UserProfile | null> => {
      if (!user?.id) return null;

      const { data, error } = await supabase
        .from("profiles")
        .select("id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end")
        .eq("id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return data as UserProfile;
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2,
  });
}

type ProfileUpdatableFields = Pick<
  ProfileUpdate,
  "full_name" | "company_name" | "website_url" | "avatar_url" | "email_preferences"
>;

export function useUpdateProfile() {
  const supabase = createClient();
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (updates: ProfileUpdatableFields) => {
      if (!user?.id) throw new Error("Not authenticated");

      const { data, error } = await supabase
        .from("profiles")
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq("id", user.id)
        .select("id, email, full_name, company_name, website_url, avatar_url, plan, scans_used, scan_limit, created_at, billing_cycle_end")
        .single();

      if (error) throw new Error(error.message);
      return data as UserProfile;
    },
    onSuccess: (data) => {
      if (user?.id) {
        queryClient.setQueryData(profileKeys.byUser(user.id), data);
      }
      refreshProfile();
    },
  });
}

