import { useAuth } from "@/contexts/AuthContext";
import type { Referral } from "@/types";
import type { ReferralInsert } from "@/types/database";

export const referralKeys = {
  all: ["referrals"] as const,
  byUser: (userId: string) => ["referrals", userId] as const,
  code: (userId: string) => ["referral-code", userId] as const,
};

export function useReferrals() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: referralKeys.byUser(user?.id ?? ""),
    queryFn: async (): Promise<Referral[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("referrals")
        .select("*")
        .eq("referrer_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data ?? []) as Referral[];
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2,
  });
}

export function useReferralStats() {
  const { data: referrals = [], isLoading, isError } = useReferrals();

  const totalReferred = referrals.length;
  const signedUp = referrals.filter((r) => r.status === "signed_up" || r.status === "converted" || r.status === "rewarded").length;
  const converted = referrals.filter((r) => r.status === "converted" || r.status === "rewarded").length;
  const rewarded = referrals.filter((r) => r.status === "rewarded").length;

  return { totalReferred, signedUp, converted, rewarded, isLoading, isError };
}

export function useReferralCode() {
  const supabase = createClient();
  const { user, profile, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  const generateCode = useMutation({
    mutationFn: async (): Promise<string> => {
      if (!user?.id) throw new Error("Not authenticated");

      const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789";
      let code = "";
      for (let i = 0; i < 8; i++) {
        code += chars[Math.floor(Math.random() * chars.length)];
      }

      const { data, error } = await supabase
        .from("profiles")
        .update({ referral_code: code })
        .eq("id", user.id)
        .select("referral_code")
        .single();

      if (error) throw new Error(error.message);
      return (data as { referral_code: string }).referral_code;
    },
    onSuccess: () => {
      void refreshProfile();
      void queryClient.invalidateQueries({ queryKey: referralKeys.code(user?.id ?? "") });
    },
    onError: (error: unknown) => {
      const message = error instanceof Error ? error.message : "Failed to generate referral code";
      toast.error(message);
    },
  });

  return {
    code: profile?.referral_code ?? null,
    isGenerating: generateCode.isPending,
    generate: generateCode.mutate,
  };
}

export function useCreateReferral() {
  const supabase = createClient();

  return useMutation({
    mutationFn: async ({
      referrerCode,
      referredEmail,
      referredId,
    }: {
      referrerCode: string;
      referredEmail: string;
      referredId: string;
    }): Promise<void> => {
      const { data: referrer, error: lookupError } = await supabase
        .from("profiles")
        .select("id")
        .eq("referral_code", referrerCode)
        .single();

      if (lookupError || !referrer) return;

      const insert: ReferralInsert = {
        referrer_id: referrer.id,
        referred_email: referredEmail,
        referred_id: referredId,
        status: "signed_up",
      };

      const { error: insertError } = await supabase.from("referrals").insert(insert);
      if (insertError) throw new Error(insertError.message);
    },
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { CroPillar } from "@/types";
import type { ScanResultRow } from "@/types/database";

export interface PillarDelta {
  pillar: CroPillar;
  previous: number;
  current: number;
  delta: number;
}

export interface ScanComparison {
  hasPrevious: boolean;
  previousScore: number;
  currentScore: number;
  scoreDelta: number;
  pillarDeltas: PillarDelta[];
  previousScanId: string;
}

const EMPTY_COMPARISON: ScanComparison = {
  hasPrevious: false,
  previousScore: 0,
  currentScore: 0,
  scoreDelta: 0,
  pillarDeltas: [],
  previousScanId: "",
};

export const scanComparisonKeys = {
  comparison: (scanId: string) => ["scan-comparison", scanId] as const,
};

export function useScanComparison(scanId: string | undefined, url: string | undefined) {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanComparisonKeys.comparison(scanId ?? ""),
    queryFn: async (): Promise<ScanComparison> => {
      if (!scanId || !url || !user?.id) return EMPTY_COMPARISON;

      const urlHash = url.toLowerCase().trim();

      const { data: historyRows, error: historyError } = await supabase
        .from("scan_history")
        .select("scan_id, score, scanned_at")
        .eq("user_id", user.id)
        .eq("url_hash", urlHash)
        .order("scanned_at", { ascending: true });

      if (historyError || !historyRows || historyRows.length < 2) return EMPTY_COMPARISON;

      const currentIndex = (historyRows as Array<{ scan_id: string; score: number; scanned_at: string }>)
        .findIndex((r) => r.scan_id === scanId);

      if (currentIndex <= 0) return EMPTY_COMPARISON;

      const currentEntry = historyRows[currentIndex] as { scan_id: string; score: number };
      const previousEntry = historyRows[currentIndex - 1] as { scan_id: string; score: number };

      const { data: prevResults, error: prevError } = await supabase
        .from("scan_results")
        .select("pillar, score")
        .eq("scan_id", previousEntry.scan_id);

      if (prevError || !prevResults) return EMPTY_COMPARISON;

      const { data: currResults, error: currError } = await supabase
        .from("scan_results")
        .select("pillar, score")
        .eq("scan_id", scanId);

      if (currError || !currResults) return EMPTY_COMPARISON;

      const prevMap = new Map<string, number>();
      for (const r of prevResults as Pick<ScanResultRow, "pillar" | "score">[]) {
        prevMap.set(r.pillar, r.score);
      }

      const pillarDeltas: PillarDelta[] = [];
      for (const r of currResults as Pick<ScanResultRow, "pillar" | "score">[]) {
        const prevScore = prevMap.get(r.pillar);
        if (prevScore !== undefined) {
          pillarDeltas.push({
            pillar: r.pillar as CroPillar,
            previous: prevScore,
            current: r.score,
            delta: r.score - prevScore,
          });
        }
      }

      return {
        hasPrevious: true,
        previousScore: previousEntry.score,
        currentScore: currentEntry.score,
        scoreDelta: currentEntry.score - previousEntry.score,
        pillarDeltas,
        previousScanId: previousEntry.scan_id,
      };
    },
    enabled: !!scanId && !!url && !!user?.id,
    staleTime: 1000 * 60 * 5,
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { ScanHistoryEntry } from "@/types";

export const scanHistoryKeys = {
  all: ["scan-history"] as const,
  byUrl: (urlHash: string) => ["scan-history", "url", urlHash] as const,
  allUrls: (userId: string) => ["scan-history", "all-urls", userId] as const,
};

function rowToEntry(row: Record<string, unknown>): ScanHistoryEntry {
  return {
    id: row.id as string,
    user_id: row.user_id as string,
    url_hash: row.url_hash as string,
    url: row.url as string,
    scan_id: row.scan_id as string,
    score: row.score as number,
    pillar_scores: (row.pillar_scores as ScanHistoryEntry["pillar_scores"]) ?? null,
    scanned_at: row.scanned_at as string,
  };
}

export function useScanHistory(urlHash: string) {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanHistoryKeys.byUrl(urlHash),
    queryFn: async (): Promise<ScanHistoryEntry[]> => {
      if (!urlHash || !user?.id) return [];

      const { data, error } = await supabase
        .from("scan_history")
        .select("*")
        .eq("user_id", user.id)
        .eq("url_hash", urlHash)
        .order("scanned_at", { ascending: true });

      if (error) throw new Error(error.message);
      return (data as Record<string, unknown>[]).map(rowToEntry);
    },
    enabled: !!urlHash && !!user?.id,
    staleTime: 1000 * 60 * 5,
  });
}

export interface UrlHistoryGroup {
  url: string;
  url_hash: string;
  entries: ScanHistoryEntry[];
  latestScore: number;
  firstScore: number;
  delta: number;
  latestScanId: string;
}

export function useAllUrlHistory() {
  const supabase = createClient();
  const { user } = useAuth();

  return useQuery({
    queryKey: scanHistoryKeys.allUrls(user?.id ?? ""),
    queryFn: async (): Promise<UrlHistoryGroup[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("scan_history")
        .select("*")
        .eq("user_id", user.id)
        .order("scanned_at", { ascending: true });

      if (error) throw new Error(error.message);

      const rows = (data as Record<string, unknown>[]).map(rowToEntry);

      const groupMap = new Map<string, ScanHistoryEntry[]>();
      for (const entry of rows) {
        const existing = groupMap.get(entry.url_hash);
        if (existing) {
          existing.push(entry);
        } else {
          groupMap.set(entry.url_hash, [entry]);
        }
      }

      const groups: UrlHistoryGroup[] = [];
      for (const [urlHash, entries] of groupMap) {
        const firstEntry = entries[0];
        const lastEntry = entries[entries.length - 1];
        groups.push({
          url: lastEntry.url,
          url_hash: urlHash,
          entries,
          latestScore: lastEntry.score,
          firstScore: firstEntry.score,
          delta: lastEntry.score - firstEntry.score,
          latestScanId: lastEntry.scan_id,
        });
      }

      groups.sort((a, b) => {
        const aLast = a.entries[a.entries.length - 1].scanned_at;
        const bLast = b.entries[b.entries.length - 1].scanned_at;
        return bLast.localeCompare(aLast);
      });

      return groups;
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2,
  });
}

'use client';

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { PillarResult, Scan, TeamBranding, Finding } from "@/types";
import type { DbFinding, ScanResultRow } from "@/types/database";

export const shareReportKeys = {
  publicScan: (token: string) => ["public-scan", token] as const,
};

export interface PublicScanPayload {
  scan: Omit<Scan, "user_id">;
  results: PillarResult[];
  teamBranding: TeamBranding | null;
}

export function useGenerateShareLink() {
  const supabase = createClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<string> => {
      const token = crypto.randomUUID();
      const { error } = await supabase
        .from("scans")
        .update({ share_token: token, is_public: true })
        .eq("id", scanId);

      if (error) throw new Error(error.message);
      return `${window.location.origin}/r/${token}`;
    },
    onSuccess: (_url, scanId) => {
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
      queryClient.invalidateQueries({ queryKey: ["scans"] });
    },
  });
}

export function useRevokeShareLink() {
  const supabase = createClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      const { error } = await supabase
        .from("scans")
        .update({ share_token: null, is_public: false })
        .eq("id", scanId);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, scanId) => {
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
      queryClient.invalidateQueries({ queryKey: ["scans"] });
    },
  });
}

function dbFindingToFinding(f: DbFinding): Finding {
  return {
    id: f.id,
    title: f.title,
    severity: f.severity,
    current_state: f.current_state,
    recommendation: f.recommendation,
    ai_suggestion: f.ai_suggestion,
    is_premium: f.is_premium,
    effort: f.effort,
    estimated_lift: f.estimated_lift,
    category: f.category,
  };
}

function rowToPillarResult(row: ScanResultRow): PillarResult {
  return {
    id: row.id,
    scan_id: row.scan_id,
    pillar: row.pillar,
    score: row.score,
    weight: row.weight,
    benchmark: row.benchmark,
    findings: (row.findings ?? []).map(dbFindingToFinding),
  };
}

export function usePublicScan(token: string) {
  return useQuery({
    queryKey: shareReportKeys.publicScan(token),
    queryFn: async (): Promise<PublicScanPayload> => {
      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
      const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

      if (!supabaseUrl || !supabaseKey) {
        throw new Error("Missing Supabase environment variables");
      }

      const res = await fetch(
        `${supabaseUrl}/functions/v1/public-report?token=${encodeURIComponent(token)}`,
        {
          headers: {
            apikey: supabaseKey,
            "Content-Type": "application/json",
          },
        }
      );

      if (res.status === 404) throw new Error("NOT_FOUND");
      if (!res.ok) throw new Error(`Failed to load public report: ${res.status}`);

      const json = (await res.json()) as {
        scan: Omit<Scan, "user_id">;
        results: ScanResultRow[];
        teamBranding?: TeamBranding;
      };

      return {
        scan: json.scan,
        results: json.results.map(rowToPillarResult),
        teamBranding: json.teamBranding ?? null,
      };
    },
    enabled: !!token,
    staleTime: 1000 * 60 * 5,
    retry: (failureCount, error) => {
      if (error instanceof Error && error.message === "NOT_FOUND") return false;
      return failureCount < 2;
    },
  });
}

