'use client';

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { WebhookEndpoint } from "@/types/index";
import type { WebhookEndpointInsert } from "@/types/database";

export const webhookKeys = {
  all: ["webhook_endpoints"] as const,
};

export function useWebhooks() {
  const supabase = createClient();
  const { profile } = useAuth();
  const userId = profile?.id;

  return useQuery({
    queryKey: webhookKeys.all,
    queryFn: async (): Promise<WebhookEndpoint[]> => {
      if (!userId) return [];

      const { data, error } = await supabase
        .from("webhook_endpoints")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return data as WebhookEndpoint[];
    },
    enabled: !!userId,
    staleTime: 1000 * 60,
  });
}

interface CreateWebhookInput {
  url: string;
  events?: string[];
}

export function useCreateWebhook() {
  const supabase = createClient();
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ url, events = ["scan.completed"] }: CreateWebhookInput): Promise<WebhookEndpoint> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const secret = crypto.randomUUID().replace(/-/g, "") + crypto.randomUUID().replace(/-/g, "");

      const insert: WebhookEndpointInsert = { user_id: userId, url, secret, events, is_active: true };

      const { data, error } = await supabase
        .from("webhook_endpoints")
        .insert(insert)
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return data as WebhookEndpoint;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

export function useDeleteWebhook() {
  const supabase = createClient();
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string): Promise<void> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("webhook_endpoints")
        .delete()
        .eq("id", id)
        .eq("user_id", userId);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

export function useToggleWebhook() {
  const supabase = createClient();
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, is_active }: { id: string; is_active: boolean }): Promise<void> => {
      const userId = profile?.id;
      if (!userId) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("webhook_endpoints")
        .update({ is_active })
        .eq("id", id)
        .eq("user_id", userId);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.all });
    },
  });
}

