450	async function fetchBillingStats(): Promise<BillingStats> {
451	  const { data, error } = await supabase
452	    .from("profiles")
453	    .select("plan");
454	
455	  if (error) throw new Error(error.message);
456	
457	  const profiles = data ?? [];
458	
459	  const planDistribution: PlanDistribution = { free: 0, pro: 0, agency: 0 };
460	
461	  for (const p of profiles) {
462	    const plan = p.plan as keyof PlanDistribution;
463	    if (plan in planDistribution) {
464	      planDistribution[plan]++;
