472	  const annualProjection = mrr * 12;
473	
474	  const activeSubscriptions = planDistribution.pro + planDistribution.agency;
475	
476	  return {
477	    mrr,
478	    annualProjection,
479	    activeSubscriptions,
480	    freeUsers: planDistribution.free,
