1694	async function fetchAdminUsers({
1695	  page,
1696	  pageSize,
1697	  filter,
1698	  sortColumn,
1699	  sortAsc,

1700	}: FetchAdminUsersParams): Promise<AdminUsersResult> {
1701	  let query = supabase
1702	    .from("profiles")
1703	    .select("*", { count: "exact" });
1704	
1705	  if (filter.search) {
1706	    // Use ilike for case-insensitive search across email and full_name
1707	    query = query.or(
1708	      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
1709	    );
1710	  }
1711	
1712	  if (filter.plan) {
1713	    query = query.eq("plan", filter.plan);
1714	  }
1715	
1716	  if (filter.role) {
1717	    query = query.eq("role", filter.role);
1718	  }
1719	
1720	  const from = page * pageSize;
1721	  const to = from + pageSize - 1;
1722	
1723	  query = query
1724	    .order(sortColumn as string, { ascending: sortAsc })
1725	    .range(from, to);
1726	
1727	  const { data, count, error } = await query;
1728	
1729	  if (error) throw new Error(error.message);
1730	
1731	  return {
1732	    users: (data ?? []) as ProfileRow[],
1733	    total: count ?? 0,
