1762	
1763	async function fetchAllUsersForExport(filter: AdminUsersFilter): Promise<string> {
1764	  let query = supabase
1765	    .from("profiles")
1766	    .select("*")
1767	    .order("created_at", { ascending: false });
1768	
1769	  if (filter.search) {
1770	    query = query.or(
1771	      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
1772	    );
1773	  }
1774	  if (filter.plan) {
1775	    query = query.eq("plan", filter.plan);
1776	  }
1777	  if (filter.role) {
1778	    query = query.eq("role", filter.role);
1779	  }
1780	
1781	  const { data, error } = await query;
1782	  if (error) throw new Error(error.message);
1783	
1784	  const users = (data ?? []) as ProfileRow[];
1785	
1786	  const headers = ["Email", "Full Name", "Plan", "Role", "Scans Used", "Scan Limit", "Created At", "Is Banned"];
1787	  const rows = users.map((u) => [
1788	    u.email ?? "",
1789	    u.full_name ?? "",
1790	    u.plan,
1791	    u.role,
1792	    String(u.scans_used),
1793	    String(u.scan_limit),
1794	    format(new Date(u.created_at), "yyyy-MM-dd HH:mm:ss"),
1795	    u.is_banned ? "Yes" : "No",
1796	  ]);
1797	
1798	  const escape = (v: string) => `"${v.replace(/"/g, '""')}"`;
1799	  const csvLines = [headers.map(escape).join(","), ...rows.map((r) => r.map(escape).join(","))];
1800	  return csvLines.join("\n");
