'use client';

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { PlanType, UserRole } from "@/types/index";
import { toast } from "sonner";

async function writeAuditLog(
  adminId: string,
  action: string,
  targetType: string,
  targetId: string,
  metadata: Record<string, unknown> = {}
) {
  const supabase = createClient();
  const { error } = await supabase.from("audit_logs").insert({
    admin_id: adminId,
    action,
    target_type: targetType,
    target_id: targetId,
    metadata,
  });
  if (error) console.error("Audit log write failed:", error.message);
}

interface ChangePlanArgs {
  userId: string;
  plan: PlanType;
  previousPlan?: PlanType;
}

export function useChangePlan() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, plan, previousPlan }: ChangePlanArgs) => {
      if (!user) throw new Error("Not authenticated");

      const newLimit = plan === "agency" ? 500 : plan === "pro" ? 25 : 3;

      const { error } = await supabase.from("profiles").update({ plan, scan_limit: newLimit }).eq("id", userId);
      if (error) throw new Error(error.message);

      await writeAuditLog(user.id, "change_plan", "profile", userId, { previous_plan: previousPlan, new_plan: plan });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Plan updated successfully");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => { toast.error(`Failed to update plan: ${error.message}`); },
  });
}

interface ChangeRoleArgs { userId: string; role: UserRole; previousRole?: UserRole; }

export function useChangeRole() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, role, previousRole }: ChangeRoleArgs) => {
      if (!user) throw new Error("Not authenticated");
      const { error } = await supabase.from("profiles").update({ role }).eq("id", userId);
      if (error) throw new Error(error.message);
      await writeAuditLog(user.id, "change_role", "profile", userId, { previous_role: previousRole, new_role: role });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Role updated successfully");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
    },
    onError: (error: Error) => { toast.error(`Failed to update role: ${error.message}`); },
  });
}

interface ResetScansArgs { userId: string; previousCount: number; }

export function useResetScanCount() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, previousCount }: ResetScansArgs) => {
      if (!user) throw new Error("Not authenticated");
      const { error } = await supabase.from("profiles").update({ scans_used: 0 }).eq("id", userId);
      if (error) throw new Error(error.message);
      await writeAuditLog(user.id, "reset_scan_count", "profile", userId, { previous_scans_used: previousCount });
    },
    onSuccess: (_, { userId }) => {
      toast.success("Scan count reset to 0");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
    },
    onError: (error: Error) => { toast.error(`Failed to reset scan count: ${error.message}`); },
  });
}

interface ToggleBanArgs { userId: string; ban: boolean; }

export function useToggleBan() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userId, ban }: ToggleBanArgs) => {
      if (!user) throw new Error("Not authenticated");
      const { error } = await supabase.from("profiles").update({ is_banned: ban }).eq("id", userId);
      if (error) throw new Error(error.message);
      await writeAuditLog(user.id, ban ? "ban_user" : "unban_user", "profile", userId, {});
    },
    onSuccess: (_, { ban, userId }) => {
      toast.success(ban ? "User banned" : "User unbanned");
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "user", userId] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => { toast.error(`Failed to update ban status: ${error.message}`); },
  });
}

interface BulkChangePlanArgs { userIds: string[]; plan: PlanType; }

export function useBulkChangePlan() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userIds, plan }: BulkChangePlanArgs) => {
      if (!user) throw new Error("Not authenticated");
      const newLimit = plan === "agency" ? 500 : plan === "pro" ? 25 : 3;
      await Promise.all(
        userIds.map((userId) =>
          supabase.from("profiles").update({ plan, scan_limit: newLimit }).eq("id", userId).then(({ error }) => {
            if (error) throw new Error(error.message);
          })
        )
      );
      await writeAuditLog(user.id, "bulk_change_plan", "profile", "bulk", { user_ids: userIds, new_plan: plan, count: userIds.length });
    },
    onSuccess: (_, { userIds, plan }) => {
      toast.success(`Updated ${userIds.length} users to ${plan} plan`);
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => { toast.error(`Bulk plan change failed: ${error.message}`); },
  });
}

interface BulkResetScansArgs { userIds: string[]; }

export function useBulkResetScans() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ userIds }: BulkResetScansArgs) => {
      if (!user) throw new Error("Not authenticated");
      await Promise.all(
        userIds.map((userId) =>
          supabase.from("profiles").update({ scans_used: 0 }).eq("id", userId).then(({ error }) => {
            if (error) throw new Error(error.message);
          })
        )
      );
      await writeAuditLog(user.id, "bulk_reset_scans", "profile", "bulk", { user_ids: userIds, count: userIds.length });
    },
    onSuccess: (_, { userIds }) => {
      toast.success(`Reset scan count for ${userIds.length} users`);
      queryClient.invalidateQueries({ queryKey: ["admin", "users"] });
    },
    onError: (error: Error) => { toast.error(`Bulk reset failed: ${error.message}`); },
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { AuditLogEntry } from "./use-audit-log";

export const PLAN_PRICES: Record<string, number> = { free: 0, pro: 49, agency: 199 };

export interface PlanDistribution { free: number; pro: number; agency: number; }

export interface BillingStats {
  mrr: number;
  annualProjection: number;
  activeSubscriptions: number;
  freeUsers: number;
  planDistribution: PlanDistribution;
}

export interface PlanChangeEntry extends AuditLogEntry {
  previous_plan?: string;
  new_plan?: string;
}

async function fetchBillingStats(): Promise<BillingStats> {
  const supabase = createClient();
  const { data, error } = await supabase.from("profiles").select("plan");
  if (error) throw new Error(error.message);

  const profiles = data ?? [];
  const planDistribution: PlanDistribution = { free: 0, pro: 0, agency: 0 };

  for (const p of profiles) {
    const plan = p.plan as keyof PlanDistribution;
    if (plan in planDistribution) planDistribution[plan]++;
  }

  const mrr = planDistribution.pro * PLAN_PRICES.pro + planDistribution.agency * PLAN_PRICES.agency;

  return {
    mrr,
    annualProjection: mrr * 12,
    activeSubscriptions: planDistribution.pro + planDistribution.agency,
    freeUsers: planDistribution.free,
    planDistribution,
  };
}

async function fetchRecentPlanChanges(): Promise<PlanChangeEntry[]> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("audit_logs")
    .select("*, profiles:admin_id (email, full_name)")
    .eq("action", "change_plan")
    .order("created_at", { ascending: false })
    .limit(20);

  if (error) throw new Error(error.message);

  return (data ?? []).map((row) => {
    const profileData = row.profiles as { email: string; full_name: string | null } | null;
    const metadata = row.metadata as Record<string, string>;
    return {
      id: row.id,
      admin_id: row.admin_id,
      action: row.action,
      target_type: row.target_type,
      target_id: row.target_id,
      metadata: row.metadata as Record<string, unknown>,
      created_at: row.created_at,
      admin_email: profileData?.email,
      admin_name: profileData?.full_name ?? undefined,
      previous_plan: metadata?.previous_plan,
      new_plan: metadata?.new_plan,
    };
  });
}

export function useAdminBilling() {
  return useQuery({ queryKey: ["admin", "billing"], queryFn: fetchBillingStats, staleTime: 60_000 });
}

export function useRecentPlanChanges() {
  return useQuery({ queryKey: ["admin", "plan-changes"], queryFn: fetchRecentPlanChanges, staleTime: 30_000 });
}

'use client';

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import type { ScanRow } from "@/types/database";
import type { ScanStatus } from "@/types/index";
import { toast } from "sonner";

async function writeAuditLog(adminId: string, action: string, targetType: string, targetId: string, metadata: Record<string, unknown> = {}) {
  const supabase = createClient();
  const { error } = await supabase.from("audit_logs").insert({ admin_id: adminId, action, target_type: targetType, target_id: targetId, metadata });
  if (error) console.error("Audit log write failed:", error.message);
}

export interface AdminScanRow extends ScanRow {
  user_email?: string;
  user_name?: string;
}

export interface AdminScansFilter {
  search?: string;
  status?: ScanStatus | "";
  scoreLte?: number;
  scoreGte?: number;
  dateFrom?: string;
  dateTo?: string;
}

export interface AdminScansResult { scans: AdminScanRow[]; total: number; }
export interface AdminScanStats { totalScans: number; avgScore: number; failedScans: number; scansToday: number; }

interface FetchAdminScansParams { page: number; pageSize: number; filter: AdminScansFilter; sortColumn: keyof ScanRow; sortAsc: boolean; }

async function fetchAdminScans({ page, pageSize, filter, sortColumn, sortAsc }: FetchAdminScansParams): Promise<AdminScansResult> {
  const supabase = createClient();
  let query = supabase
    .from("scans")
    .select("*, profiles:user_id (email, full_name)", { count: "exact" })
    .order(sortColumn as string, { ascending: sortAsc });

  if (filter.status) query = query.eq("status", filter.status);
  if (filter.scoreGte !== undefined && filter.scoreGte > 0) query = query.gte("overall_score", filter.scoreGte);
  if (filter.scoreLte !== undefined && filter.scoreLte < 100) query = query.lte("overall_score", filter.scoreLte);
  if (filter.dateFrom) query = query.gte("created_at", filter.dateFrom);
  if (filter.dateTo) query = query.lte("created_at", filter.dateTo);

  const from = page * pageSize;
  const to = from + pageSize - 1;
  query = query.range(from, to);

  const { data, count, error } = await query;
  if (error) throw new Error(error.message);

  const scans: AdminScanRow[] = (data ?? []).map((row) => {
    const profileData = row.profiles as { email: string; full_name: string | null } | null;
    return {
      id: row.id, user_id: row.user_id, url: row.url, favicon_url: row.favicon_url,
      page_title: row.page_title, page_type: row.page_type, status: row.status,
      overall_score: row.overall_score, issues_found: row.issues_found, critical_issues: row.critical_issues,
      warnings: row.warnings, quick_wins: row.quick_wins, screenshot_url: row.screenshot_url,
      device: row.device, error_message: row.error_message, created_at: row.created_at,
      completed_at: row.completed_at, user_email: profileData?.email, user_name: profileData?.full_name ?? undefined,
    };
  });

  const filtered = filter.search
    ? scans.filter((s) => s.url.toLowerCase().includes(filter.search!.toLowerCase()) || (s.user_email ?? "").toLowerCase().includes(filter.search!.toLowerCase()))
    : scans;

  return { scans: filtered, total: filter.search ? filtered.length : (count ?? 0) };
}

async function fetchAdminScanStats(): Promise<AdminScanStats> {
  const supabase = createClient();
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const [
    { count: totalScans, error: totalError },
    { count: failedScans, error: failedError },
    { count: scansToday, error: todayError },
    { data: scoreData, error: scoreError },
  ] = await Promise.all([
    supabase.from("scans").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "failed"),
    supabase.from("scans").select("*", { count: "exact", head: true }).gte("created_at", todayStart.toISOString()),
    supabase.from("scans").select("overall_score").eq("status", "completed").not("overall_score", "is", null),
  ]);

  if (totalError) throw new Error(totalError.message);
  if (failedError) throw new Error(failedError.message);
  if (todayError) throw new Error(todayError.message);
  if (scoreError) throw new Error(scoreError.message);

  const scores = (scoreData ?? []).map((r) => r.overall_score as number).filter((s) => s !== null);
  const avgScore = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;

  return { totalScans: totalScans ?? 0, avgScore, failedScans: failedScans ?? 0, scansToday: scansToday ?? 0 };
}

export function useAdminScans(params: { page?: number; pageSize?: number; filter?: AdminScansFilter; sortColumn?: keyof ScanRow; sortAsc?: boolean; }) {
  const { page = 0, pageSize = 25, filter = {}, sortColumn = "created_at", sortAsc = false } = params;
  return useQuery({
    queryKey: ["admin", "scans", { page, pageSize, filter, sortColumn, sortAsc }],
    queryFn: () => fetchAdminScans({ page, pageSize, filter, sortColumn, sortAsc }),
    staleTime: 30_000,
    placeholderData: (prev) => prev,
  });
}

export function useAdminScanStats() {
  return useQuery({ queryKey: ["admin", "scan-stats"], queryFn: fetchAdminScanStats, staleTime: 60_000 });
}

export function useDeleteScan() {
  const supabase = createClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string) => {
      const { error: resultsError } = await supabase.from("scan_results").delete().eq("scan_id", scanId);
      if (resultsError) throw new Error(resultsError.message);
      const { error } = await supabase.from("scans").delete().eq("id", scanId);
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Scan deleted");
      queryClient.invalidateQueries({ queryKey: ["admin", "scans"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "scan-stats"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => { toast.error(`Failed to delete scan: ${error.message}`); },
  });
}

export function useAdminRetryScan() {
  const supabase = createClient();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async (scanId: string) => {
      if (!user) throw new Error("Not authenticated");
      const { error: updateError } = await supabase.from("scans").update({ status: "pending", completed_at: null, error_message: null }).eq("id", scanId);
      if (updateError) throw new Error(updateError.message);
      const { error: fnError } = await supabase.functions.invoke("analyze-url", { body: { scanId } });
      if (fnError) console.warn("analyze-url function invocation warning:", fnError.message);
      await writeAuditLog(user.id, "retry_scan", "scan", scanId, {});
    },
    onSuccess: () => {
      toast.success("Scan queued for retry");
      queryClient.invalidateQueries({ queryKey: ["admin", "scans"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "scan-stats"] });
    },
    onError: (error: Error) => { toast.error(`Failed to retry scan: ${error.message}`); },
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { format, subDays, startOfDay } from "date-fns";

export interface AdminStats {
  totalUsers: number;
  totalScans: number;
  activeUsers: number;
  failedScans: number;
  scanSuccessRate: number;
  newUsersToday: number;
  avgScoreThisMonth: number;
  scansThisMonth: number;
}

export interface UserGrowthDataPoint { date: string; count: number; cumulative: number; }
export interface ScanVolumeDataPoint { day: string; total: number; completed: number; failed: number; }

async function fetchAdminStats(): Promise<AdminStats> {
  const supabase = createClient();
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const todayMidnightUTC = new Date();
  todayMidnightUTC.setUTCHours(0, 0, 0, 0);
  const firstOfMonth = new Date();
  firstOfMonth.setDate(1);
  firstOfMonth.setHours(0, 0, 0, 0);

  const [
    { count: totalUsers, error: usersError },
    { count: totalScans, error: scansError },
    { count: failedScans, error: failedError },
    { count: completedScans, error: completedError },
    { data: activeData, error: activeError },
    { count: newUsersToday, error: newUsersTodayError },
    { count: scansThisMonth, error: scansMonthError },
    { data: monthScores, error: monthScoresError },
  ] = await Promise.all([
    supabase.from("profiles").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "failed"),
    supabase.from("scans").select("*", { count: "exact", head: true }).eq("status", "completed"),
    supabase.from("scans").select("user_id").gte("created_at", sevenDaysAgo),
    supabase.from("profiles").select("*", { count: "exact", head: true }).gte("created_at", todayMidnightUTC.toISOString()),
    supabase.from("scans").select("*", { count: "exact", head: true }).gte("created_at", firstOfMonth.toISOString()),
    supabase.from("scans").select("overall_score").eq("status", "completed").gte("created_at", firstOfMonth.toISOString()).not("overall_score", "is", null),
  ]);

  if (usersError) throw new Error(usersError.message);
  if (scansError) throw new Error(scansError.message);
  if (failedError) throw new Error(failedError.message);
  if (completedError) throw new Error(completedError.message);
  if (activeError) throw new Error(activeError.message);
  if (newUsersTodayError) throw new Error(newUsersTodayError.message);
  if (scansMonthError) throw new Error(scansMonthError.message);
  if (monthScoresError) throw new Error(monthScoresError.message);

  const uniqueActiveUsers = new Set((activeData ?? []).map((r) => r.user_id)).size;
  const total = totalScans ?? 0;
  const completed = completedScans ?? 0;
  const scanSuccessRate = total > 0 ? Math.round((completed / total) * 1000) / 10 : 0;
  const scores = (monthScores ?? []).map((r) => r.overall_score as number).filter((s) => s !== null && s !== undefined);
  const avgScoreThisMonth = scores.length > 0 ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;

  return {
    totalUsers: totalUsers ?? 0, totalScans: total, activeUsers: uniqueActiveUsers,
    failedScans: failedScans ?? 0, scanSuccessRate, newUsersToday: newUsersToday ?? 0,
    avgScoreThisMonth, scansThisMonth: scansThisMonth ?? 0,
  };
}

async function fetchUserGrowth(): Promise<UserGrowthDataPoint[]> {
  const supabase = createClient();
  const thirtyDaysAgo = subDays(new Date(), 30).toISOString();

  const { data, error } = await supabase
    .from("profiles")
    .select("created_at")
    .gte("created_at", thirtyDaysAgo)
    .order("created_at", { ascending: true });

  if (error) throw new Error(error.message);

  const countsByDate: Record<string, number> = {};
  for (const row of data ?? []) {
    const day = format(new Date(row.created_at), "MMM d");
    countsByDate[day] = (countsByDate[day] ?? 0) + 1;
  }

  const result: UserGrowthDataPoint[] = [];
  let cumulative = 0;
  for (let i = 29; i >= 0; i--) {
    const d = subDays(new Date(), i);
    const dateLabel = format(d, "MMM d");
    const count = countsByDate[dateLabel] ?? 0;
    cumulative += count;
    result.push({ date: dateLabel, count, cumulative });
  }

  return result;
}

async function fetchScanVolume(): Promise<ScanVolumeDataPoint[]> {
  const supabase = createClient();
  const sevenDaysAgo = subDays(startOfDay(new Date()), 6).toISOString();

  const { data, error } = await supabase
    .from("scans")
    .select("created_at, status")
    .gte("created_at", sevenDaysAgo)
    .order("created_at", { ascending: true });

  if (error) throw new Error(error.message);

  const byDay: Record<string, { total: number; completed: number; failed: number }> = {};

  for (const row of data ?? []) {
    const day = format(new Date(row.created_at), "EEE");
    if (!byDay[day]) byDay[day] = { total: 0, completed: 0, failed: 0 };
    byDay[day].total++;
    if (row.status === "completed") byDay[day].completed++;
    if (row.status === "failed") byDay[day].failed++;
  }

  const result: ScanVolumeDataPoint[] = [];
  for (let i = 6; i >= 0; i--) {
    const day = format(subDays(new Date(), i), "EEE");
    const entry = byDay[day] ?? { total: 0, completed: 0, failed: 0 };
    result.push({ day, ...entry });
  }

  return result;
}

export function useAdminStats() {
  return useQuery({ queryKey: ["admin", "stats"], queryFn: fetchAdminStats, staleTime: 60_000 });
}

export function useUserGrowth() {
  return useQuery({ queryKey: ["admin", "user-growth"], queryFn: fetchUserGrowth, staleTime: 5 * 60_000 });
}

export function useScanVolume() {
  return useQuery({ queryKey: ["admin", "scan-volume"], queryFn: fetchScanVolume, staleTime: 5 * 60_000 });
}

'use client';

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { ProfileRow } from "@/types/database";
import { toast } from "sonner";

export interface AtRiskUser extends ProfileRow {
  has_failed_scans: boolean;
  never_scanned: boolean;
  at_scan_limit: boolean;
  last_scan_date: string | null;
}

export interface SupportStats {
  usersAtLimit: number;
  usersWithFailedScans: number;
  newSignupsLastWeek: number;
}

export type SupportStatus = "open" | "in_progress" | "resolved" | "closed";
export type SupportPriority = "low" | "normal" | "high" | "urgent";

export interface SupportRequest {
  id: string;
  user_id: string | null;
  user_email: string;
  subject: string;
  message: string;
  status: SupportStatus;
  priority: SupportPriority;
  admin_notes: string | null;
  created_at: string;
  updated_at: string;
  resolved_at: string | null;
  user_name?: string | null;
}

async function fetchAtRiskUsers(): Promise<AtRiskUser[]> {
  const supabase = createClient();
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

  const { data: profiles, error: profilesError } = await supabase.from("profiles").select("*").order("created_at", { ascending: false }).limit(200);
  if (profilesError) throw new Error(profilesError.message);

  const { data: failedScansData, error: failedError } = await supabase.from("scans").select("user_id").eq("status", "failed").gte("created_at", sevenDaysAgo);
  if (failedError) throw new Error(failedError.message);

  const { data: lastScans, error: lastScansError } = await supabase.from("scans").select("user_id, created_at").order("created_at", { ascending: false });
  if (lastScansError) throw new Error(lastScansError.message);

  const failedUserIds = new Set((failedScansData ?? []).map((r) => r.user_id));
  const lastScanMap = new Map<string, string>();
  for (const scan of lastScans ?? []) {
    if (!lastScanMap.has(scan.user_id)) lastScanMap.set(scan.user_id, scan.created_at);
  }

  const atRisk: AtRiskUser[] = [];
  for (const profile of profiles ?? []) {
    const p = profile as ProfileRow;
    const atLimit = p.scans_used >= p.scan_limit;
    const hasFailed = failedUserIds.has(p.id);
    const neverScanned = !lastScanMap.has(p.id);
    const lastScanDate = lastScanMap.get(p.id) ?? null;

    if (atLimit || hasFailed || neverScanned) {
      atRisk.push({ ...p, has_failed_scans: hasFailed, never_scanned: neverScanned, at_scan_limit: atLimit, last_scan_date: lastScanDate });
    }
  }

  return atRisk.sort((a, b) => {
    const scoreA = (a.at_scan_limit ? 3 : 0) + (a.has_failed_scans ? 2 : 0) + (a.never_scanned ? 1 : 0);
    const scoreB = (b.at_scan_limit ? 3 : 0) + (b.has_failed_scans ? 2 : 0) + (b.never_scanned ? 1 : 0);
    return scoreB - scoreA;
  });
}

async function fetchSupportStats(): Promise<SupportStats> {
  const supabase = createClient();
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

  const [
    { data: profiles, error: profilesError },
    { data: failedScans, error: failedError },
    { count: newSignups, error: signupsError },
  ] = await Promise.all([
    supabase.from("profiles").select("scans_used, scan_limit"),
    supabase.from("scans").select("user_id").eq("status", "failed").gte("created_at", sevenDaysAgo),
    supabase.from("profiles").select("*", { count: "exact", head: true }).gte("created_at", sevenDaysAgo),
  ]);

  if (profilesError) throw new Error(profilesError.message);
  if (failedError) throw new Error(failedError.message);
  if (signupsError) throw new Error(signupsError.message);

  const usersAtLimit = (profiles ?? []).filter((p) => p.scans_used >= p.scan_limit).length;
  const usersWithFailedScans = new Set((failedScans ?? []).map((r) => r.user_id)).size;

  return { usersAtLimit, usersWithFailedScans, newSignupsLastWeek: newSignups ?? 0 };
}

async function fetchSupportRequests(filter?: { status?: SupportStatus }): Promise<SupportRequest[]> {
  const supabase = createClient();
  let query = supabase
    .from("support_requests")
    .select("*, profiles:user_id (full_name)")
    .order("created_at", { ascending: false });

  if (filter?.status) query = query.eq("status", filter.status);

  const { data, error } = await query;
  if (error) throw new Error(error.message);

  return (data ?? []).map((row) => {
    const profileData = row.profiles as { full_name: string | null } | null;
    return {
      id: row.id, user_id: row.user_id, user_email: row.user_email,
      subject: row.subject, message: row.message, status: row.status as SupportStatus,
      priority: row.priority as SupportPriority, admin_notes: row.admin_notes,
      created_at: row.created_at, updated_at: row.updated_at, resolved_at: row.resolved_at,
      user_name: profileData?.full_name ?? null,
    };
  });
}

export function useAtRiskUsers() {
  return useQuery({ queryKey: ["admin", "at-risk-users"], queryFn: fetchAtRiskUsers, staleTime: 60_000 });
}

export function useSupportStats() {
  return useQuery({ queryKey: ["admin", "support-stats"], queryFn: fetchSupportStats, staleTime: 60_000 });
}

export function useSupportRequests(filter?: { status?: SupportStatus }) {
  return useQuery({
    queryKey: ["admin", "support-requests", filter],
    queryFn: () => fetchSupportRequests(filter),
    staleTime: 30_000,
  });
}

export function useUpdateSupportRequest() {
  const supabase = createClient();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, status, priority, admin_notes }: { id: string; status?: SupportStatus; priority?: SupportPriority; admin_notes?: string }) => {
      const updates: Record<string, unknown> = { updated_at: new Date().toISOString() };
      if (status !== undefined) {
        updates.status = status;
        if (status === "resolved" || status === "closed") updates.resolved_at = new Date().toISOString();
      }
      if (priority !== undefined) updates.priority = priority;
      if (admin_notes !== undefined) updates.admin_notes = admin_notes;

      const { error } = await supabase.from("support_requests").update(updates).eq("id", id);
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Support request updated");
      queryClient.invalidateQueries({ queryKey: ["admin", "support-requests"] });
    },
    onError: (error: Error) => { toast.error(`Failed to update request: ${error.message}`); },
  });
}

