'use client';

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

// ── Types ─────────────────────────────────────────────────────

export interface SystemStats {
  profilesCount: number;
  scansCount: number;
  scanResultsCount: number;
  screenshotsCount: number;
  supabaseConnected: boolean;
}

export interface PlanLimits {
  free: number;
  starter: number;
  growth: number;
  pro: number;
  agency: number;
}

const DEFAULT_PLAN_LIMITS: PlanLimits = { free: 3, starter: 5, growth: 25, pro: 9999, agency: 9999 };

const DEFAULT_PILLAR_WEIGHTS: Record<string, number> = {
  value_proposition: 0.25,
  cta_effectiveness: 0.20,
  trust_signals: 0.15,
  visual_hierarchy: 0.15,
  mobile_experience: 0.10,
  content_copy: 0.10,
  page_performance: 0.05,
};

// ── Audit log helper (local to this module) ───────────────────

async function writeSystemAuditLog(
  adminId: string,
  action: string,
  metadata: Record<string, unknown> = {}
) {
  const supabase = createClient();
  const { error } = await supabase.from("audit_logs").insert({
    admin_id: adminId,
    action,
    target_type: "system_config",
    target_id: "system",
    metadata,
  });
  if (error) {
    console.error("Audit log write failed:", error.message);
  }
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchSystemStats(): Promise<SystemStats> {
  const supabase = createClient();
  const [
    { count: profilesCount, error: profilesError },
    { count: scansCount, error: scansError },
    { count: scanResultsCount, error: resultsError },
    { count: screenshotsCount, error: screenshotsError },
  ] = await Promise.all([
    supabase.from("profiles").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }),
    supabase.from("scan_results").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }).not("screenshot_url", "is", null),
  ]);

  // Ignore unused error variables — we just check if Supabase is reachable
  void scansError;
  void resultsError;
  void screenshotsError;

  const supabaseConnected = !profilesError || profilesError.code !== "PGRST301";

  return {
    profilesCount: profilesCount ?? 0,
    scansCount: scansCount ?? 0,
    scanResultsCount: scanResultsCount ?? 0,
    screenshotsCount: screenshotsCount ?? 0,
    supabaseConnected,
  };
}

async function fetchPlanLimits(): Promise<PlanLimits> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("system_config")
    .select("value")
    .eq("key", "plan_limits")
    .single();

  if (error && error.code !== "PGRST116") throw new Error(error.message);

  if (!data?.value) return DEFAULT_PLAN_LIMITS;

  const stored = data.value as Partial<PlanLimits>;
  return {
    free: stored.free ?? DEFAULT_PLAN_LIMITS.free,
    starter: stored.starter ?? DEFAULT_PLAN_LIMITS.starter,
    growth: stored.growth ?? DEFAULT_PLAN_LIMITS.growth,
    pro: stored.pro ?? DEFAULT_PLAN_LIMITS.pro,
    agency: stored.agency ?? DEFAULT_PLAN_LIMITS.agency,
  };
}

async function fetchPillarWeights(): Promise<Record<string, number>> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("system_config")
    .select("value")
    .eq("key", "pillar_weights")
    .single();

  if (error && error.code !== "PGRST116") throw new Error(error.message);

  if (!data?.value) return DEFAULT_PILLAR_WEIGHTS;

  return { ...DEFAULT_PILLAR_WEIGHTS, ...(data.value as Record<string, number>) };
}

// ── Hooks ─────────────────────────────────────────────────────

export function useSystemStats() {
  return useQuery({
    queryKey: ["admin", "system-stats"],
    queryFn: fetchSystemStats,
    staleTime: 30_000,
  });
}

export function usePlanLimits() {
  return useQuery({
    queryKey: ["admin", "system-config", "plan-limits"],
    queryFn: fetchPlanLimits,
    staleTime: 60_000,
  });
}

export function usePillarWeights() {
  return useQuery({
    queryKey: ["admin", "system-config", "pillar-weights"],
    queryFn: fetchPillarWeights,
    staleTime: 60_000,
  });
}

export function useUpdatePlanLimits() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async (limits: PlanLimits) => {
      if (!user) throw new Error("Not authenticated");
      const supabase = createClient();

      const { error } = await supabase.from("system_config").upsert(
        {
          key: "plan_limits",
          value: limits,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "key" }
      );
      if (error) throw new Error(error.message);

      await writeSystemAuditLog(user.id, "update_plan_limits", {
        free: limits.free,
        pro: limits.pro,
        agency: limits.agency,
      });
    },
    onSuccess: () => {
      toast.success("Plan limits saved");
      queryClient.invalidateQueries({ queryKey: ["admin", "system-config", "plan-limits"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to save plan limits: ${error.message}`);
    },
  });
}

export function useUpdatePillarWeights() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async (weights: Record<string, number>) => {
      if (!user) throw new Error("Not authenticated");
      const supabase = createClient();

      const { error } = await supabase.from("system_config").upsert(
        {
          key: "pillar_weights",
          value: weights,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "key" }
      );
      if (error) throw new Error(error.message);

      await writeSystemAuditLog(user.id, "update_pillar_weights", weights);
    },
    onSuccess: () => {
      toast.success("Pillar weights saved");
      queryClient.invalidateQueries({ queryKey: ["admin", "system-config", "pillar-weights"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to save pillar weights: ${error.message}`);
    },
  });
}

export function useResetMonthlyScans() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const supabase = createClient();
      const { error } = await supabase.rpc("reset_monthly_scans");
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Monthly scan counters reset for all users");
      queryClient.invalidateQueries({ queryKey: ["admin"] });
    },
    onError: (error: Error) => {
      toast.error(`Reset failed: ${error.message}`);
    },
  });
}

export function useClearFailedScans() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const supabase = createClient();
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

      const { data: failedScans, error: fetchError } = await supabase
        .from("scans")
        .select("id")
        .eq("status", "failed")
        .lte("created_at", thirtyDaysAgo);

      if (fetchError) throw new Error(fetchError.message);

      const scanIds = (failedScans ?? []).map((s) => s.id);

      if (scanIds.length === 0) return 0;

      const { error: resultsError } = await supabase
        .from("scan_results")
        .delete()
        .in("scan_id", scanIds);

      if (resultsError) throw new Error(resultsError.message);

      const { count, error: deleteError } = await supabase
        .from("scans")
        .delete({ count: "exact" })
        .eq("status", "failed")
        .lte("created_at", thirtyDaysAgo);

      if (deleteError) throw new Error(deleteError.message);

      return count ?? 0;
    },
    onSuccess: (count) => {
      toast.success(
        count === 0
          ? "No old failed scans to clear"
          : `Cleared ${count} failed scan${count === 1 ? "" : "s"}`
      );
      queryClient.invalidateQueries({ queryKey: ["admin"] });
    },
    onError: (error: Error) => {
      toast.error(`Clear failed: ${error.message}`);
    },
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { ProfileRow, ScanRow } from "@/types/database";

interface UserDetailResult {
  profile: ProfileRow;
  scans: ScanRow[];
  totalScans: number;
}

async function fetchUserDetail(userId: string): Promise<UserDetailResult> {
  const supabase = createClient();
  const [profileResult, scansResult] = await Promise.all([
    supabase
      .from("profiles")
      .select("*")
      .eq("id", userId)
      .single(),
    supabase
      .from("scans")
      .select("*", { count: "exact" })
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .limit(20),
  ]);

  if (profileResult.error) throw new Error(profileResult.error.message);
  if (scansResult.error) throw new Error(scansResult.error.message);

  return {
    profile: profileResult.data as ProfileRow,
    scans: (scansResult.data ?? []) as ScanRow[],
    totalScans: scansResult.count ?? 0,
  };
}

export function useAdminUserDetail(userId: string) {
  return useQuery({
    queryKey: ["admin", "user", userId],
    queryFn: () => fetchUserDetail(userId),
    enabled: Boolean(userId),
    staleTime: 30_000,
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { AuditLogRow } from "@/types/database";

export interface AuditLogEntry extends AuditLogRow {
  admin_email?: string;
  admin_name?: string;
}

interface FetchAuditLogParams {
  page: number;
  pageSize: number;
  actionFilter?: string;
}

async function fetchAuditLog({
  page,
  pageSize,
  actionFilter,
}: FetchAuditLogParams): Promise<{ entries: AuditLogEntry[]; total: number }> {
  const supabase = createClient();
  let query = supabase
    .from("audit_logs")
    .select(
      `
      *,
      profiles:admin_id (
        email,
        full_name
      )
    `,
      { count: "exact" }
    )
    .order("created_at", { ascending: false });

  if (actionFilter) {
    query = query.eq("action", actionFilter);
  }

  const from = page * pageSize;
  const to = from + pageSize - 1;
  query = query.range(from, to);

  const { data, count, error } = await query;

  if (error) throw new Error(error.message);

  const entries: AuditLogEntry[] = (data ?? []).map((row) => {
    const profileData = row.profiles as { email: string; full_name: string } | null;
    return {
      id: row.id,
      admin_id: row.admin_id,
      action: row.action,
      target_type: row.target_type,
      target_id: row.target_id,
      metadata: row.metadata as Record<string, unknown>,
      created_at: row.created_at,
      admin_email: profileData?.email,
      admin_name: profileData?.full_name,
    };
  });

  return { entries, total: count ?? 0 };
}

export function useAuditLog(params: {
  page?: number;
  pageSize?: number;
  actionFilter?: string;
}) {
  const { page = 0, pageSize = 25, actionFilter } = params;

  return useQuery({
    queryKey: ["admin", "audit-log", { page, pageSize, actionFilter }],
    queryFn: () => fetchAuditLog({ page, pageSize, actionFilter }),
    staleTime: 15_000,
    placeholderData: (prev) => prev,
  });
}

'use client';

import { useQuery } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import type { ProfileRow } from "@/types/database";
import type { PlanType, UserRole } from "@/types/index";
import { format } from "date-fns";

export interface AdminUsersFilter {
  search?: string;
  plan?: PlanType | "";
  role?: UserRole | "";
}

export interface AdminUsersResult {
  users: ProfileRow[];
  total: number;
}

interface FetchAdminUsersParams {
  page: number;
  pageSize: number;
  filter: AdminUsersFilter;
  sortColumn: keyof ProfileRow;
  sortAsc: boolean;
}

const PAGE_SIZE = 20;

async function fetchAdminUsers({
  page,
  pageSize,
  filter,
  sortColumn,
  sortAsc,
}: FetchAdminUsersParams): Promise<AdminUsersResult> {
  const supabase = createClient();
  let query = supabase
    .from("profiles")
    .select("*", { count: "exact" });

  if (filter.search) {
    query = query.or(
      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
    );
  }

  if (filter.plan) {
    query = query.eq("plan", filter.plan);
  }

  if (filter.role) {
    query = query.eq("role", filter.role);
  }

  const from = page * pageSize;
  const to = from + pageSize - 1;

  query = query
    .order(sortColumn as string, { ascending: sortAsc })
    .range(from, to);

  const { data, count, error } = await query;

  if (error) throw new Error(error.message);

  return {
    users: (data ?? []) as ProfileRow[],
    total: count ?? 0,
  };
}

export function useAdminUsers(params: {
  page?: number;
  pageSize?: number;
  filter?: AdminUsersFilter;
  sortColumn?: keyof ProfileRow;
  sortAsc?: boolean;
}) {
  const {
    page = 0,
    pageSize = PAGE_SIZE,
    filter = {},
    sortColumn = "created_at",
    sortAsc = false,
  } = params;

  return useQuery({
    queryKey: ["admin", "users", { page, pageSize, filter, sortColumn, sortAsc }],
    queryFn: () => fetchAdminUsers({ page, pageSize, filter, sortColumn, sortAsc }),
    staleTime: 30_000,
    placeholderData: (prev) => prev,
  });
}

// ── Export users to CSV ───────────────────────────────────────

async function fetchAllUsersForExport(filter: AdminUsersFilter): Promise<string> {
  const supabase = createClient();
  let query = supabase
    .from("profiles")
    .select("*")
    .order("created_at", { ascending: false });

  if (filter.search) {
    query = query.or(
      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
    );
  }
  if (filter.plan) {
    query = query.eq("plan", filter.plan);
  }
  if (filter.role) {
    query = query.eq("role", filter.role);
  }

  const { data, error } = await query;
  if (error) throw new Error(error.message);

  const users = (data ?? []) as ProfileRow[];

  const headers = ["Email", "Full Name", "Plan", "Role", "Scans Used", "Scan Limit", "Created At", "Is Banned"];
  const rows = users.map((u) => [
    u.email ?? "",
    u.full_name ?? "",
    u.plan,
    u.role,
    String(u.scans_used),
    String(u.scan_limit),
    format(new Date(u.created_at), "yyyy-MM-dd HH:mm:ss"),
    u.is_banned ? "Yes" : "No",
  ]);

  const escape = (v: string) => `"${v.replace(/"/g, '""')}"`;
  const csvLines = [headers.map(escape).join(","), ...rows.map((r) => r.map(escape).join(","))];
  return csvLines.join("\n");
}

export function useExportUsers(filter: AdminUsersFilter) {
  return useQuery({
    queryKey: ["admin", "users", "export", filter],
    queryFn: () => fetchAllUsersForExport(filter),
    enabled: false, // Only run when refetch() is called manually
    staleTime: 0,
  });
}

'use client';

/**
 * Feature Flags — stored in Supabase system_config table.
 *
 * Admin hook: read + write. For read-only use in app features, use hooks/use-feature-flag.ts.
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { createClient } from "@/lib/supabase/client";
import { toast } from "sonner";

export interface FlagDefinition {
  key: string;
  label: string;
  description: string;
  defaultValue: boolean;
  category: "ui" | "feature" | "system";
  requiresSuperAdmin?: boolean;
}

export const FLAG_DEFINITIONS: FlagDefinition[] = [
  {
    key: "agent_hub_enabled",
    label: "AI Agent Hub",
    description: "Show the AI Agent Hub section in the user sidebar navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "integrations_enabled",
    label: "Integrations Page",
    description:
      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "pdf_export_enabled",
    label: "PDF Export",
    description:
      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "email_notifications_enabled",
    label: "Email Notifications",
    description:
      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "free_scan_enabled",
    label: "Public Scan (No Auth)",
    description:
      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
    defaultValue: true,
    category: "feature",
  },
  {
    key: "maintenance_mode",
    label: "Maintenance Mode",
    description:
      "Show a maintenance banner to all users. Does not block access — visual notice only.",
    defaultValue: false,
    category: "system",
    requiresSuperAdmin: true,
  },
];

const DEFAULT_FLAGS: Record<string, boolean> = Object.fromEntries(
  FLAG_DEFINITIONS.map((f) => [f.key, f.defaultValue])
);

export interface FeatureFlagsData {
  flags: Record<string, boolean>;
  updatedAt: string | null;
}

async function fetchFeatureFlags(): Promise<FeatureFlagsData> {
  const supabase = createClient();
  const { data, error } = await supabase
    .from("system_config")
    .select("value, updated_at")
    .eq("key", "feature_flags")
    .single();

  if (error && error.code !== "PGRST116") {
    // PGRST116 = row not found — that's fine, we use defaults
    throw new Error(error.message);
  }

  const stored = (data?.value ?? {}) as Record<string, boolean>;

  // Merge stored values with defaults (stored values take priority)
  const flags: Record<string, boolean> = { ...DEFAULT_FLAGS, ...stored };

  return {
    flags,
    updatedAt: data?.updated_at ?? null,
  };
}

// ── Admin hook: reads + writes ────────────────────────────────

export function useFeatureFlags() {
  return useQuery({
    queryKey: ["admin", "feature-flags"],
    queryFn: fetchFeatureFlags,
    staleTime: 60_000,
  });
}

export function useUpdateFeatureFlag() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      key,
      enabled,
      currentFlags,
    }: {
      key: string;
      enabled: boolean;
      currentFlags: Record<string, boolean>;
    }) => {
      const supabase = createClient();
      const mergedFlags = { ...currentFlags, [key]: enabled };

      const { error } = await supabase.from("system_config").upsert(
        {
          key: "feature_flags",
          value: mergedFlags,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "key" }
      );

      if (error) throw new Error(error.message);

      return { key, enabled, mergedFlags };
    },
    onSuccess: (result) => {
      const flagDef = FLAG_DEFINITIONS.find((f) => f.key === result.key);
      const label = flagDef?.label ?? result.key;
      toast.success(`${label} ${result.enabled ? "enabled" : "disabled"}`);
      // Invalidate both admin and app-level queries
      queryClient.invalidateQueries({ queryKey: ["admin", "feature-flags"] });
      queryClient.invalidateQueries({ queryKey: ["feature-flags"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to update flag: ${error.message}`);
    },
  });
}

